window.WORD_MNEMONICS_DB = window.WORD_MNEMONICS_DB || {};
Object.assign(window.WORD_MNEMONICS_DB, {
  "ubiquitous": "諧音聯想：\n諧音：你比虧特死。\n\n聯想畫面 1：這家連鎖店生意太好，到處都是，競爭對手看到都說你比虧特死，因為這品牌無所不在。\n\n聯想畫面 2：現代人手機不離身，網路訊號簡直無所不在，走到哪裡都能連線。\n\n高效擴充：字首 ubi 代表到處，quity 聯想 quality 品質，到處都有好品質。\nKK 音標：[juˋbɪkwɪtəs] -> 重音在第二音節 bi，發音時嘴型要像微笑一樣拉開。\n\n常見同義字：\n\nomnipresent（正式，無所不在的）\n\npervasive（瀰漫的，遍佈的）\n\ncommon（普通的）。",
  "ugh": "諧音聯想：\n諧音：阿（噁）\n\n聯想畫面 1：看到地上的蟑螂，他發出 ugh 的聲音，表示極度厭惡。\n\n聯想畫面 2：吃到壞掉的食物，他皺起眉頭說 ugh，趕緊吐出來。\n\n高效擴充：這是一個擬聲詞，用來表達生理上的噁心或心理上的反感。\nKK 音標：[ʊx；ɝ] -> 唸起來像喉嚨深處發出的「阿」聲。\n\n常見同義字：\nyuck（噁心，口語常用）\neew（哎唷，表示嫌棄）\ndisgust（厭惡，名詞或動詞）",
  "ugly": "諧音聯想：\n諧音：「阿格力」\n\n聯想畫面 1：大力水手裡的反派阿格力長相非常醜陋。\n\n聯想畫面 2：這棟廢棄的建築外觀實在太醜，令人厭惡。\n\n高效擴充：與 beauty（美麗）意義相反的高頻基礎形容詞。\nKK 音標：[ˋʌɡli] -> 第一音節重讀，發短促的 u 音。\n\n常見同義字：\n\nhideous（形容極度醜陋的、可怕的）\n\nunsightly（形容不美觀的、難看的）\n\nunattractive（形容沒有吸引力的、不討人喜歡的）",
  "ulcer": "諧音聯想：\n諧音：「凹死他」\n\n聯想畫面 1：胃壁被壓力腐蝕出一個凹洞形成了胃潰瘍，痛得他快死掉。\n\n聯想畫面 2：社會上道德敗壞的腐敗現象如同毒瘤一般，正在侵蝕國家的根基。\n\n高效擴充：源自拉丁文 ulcus，醫學上專指黏膜或皮膚表面組織的壞死凹陷。\nKK 音標：[ˋʌlsɚ] -> 主重音在第一個音節 ul，短母音 u 發短促的額音。\n\n常見同義字：\n\nsores（瘡、痛處，泛指皮膚或黏膜上的發炎傷口）\nwound（泛指各種外力造成的傷口或創傷）\ncanker（潰瘍或腐蝕性的事物，常用於植物或抽象道德敗壞）",
  "ultimate": "諧音聯想：\n諧音：「歐媽貼米爹」\n\n聯想畫面 1：媽媽端出終極美味的拿手好菜，告訴全家人這是最終的晚餐。\n\n聯想畫面 2：這場比賽是決定冠軍誰屬的終極之戰，也是實力的最根本展現。\n\n高效擴充：由 ultimus (最後的) 演變而來，常與 goal、goal、destiny 搭配。\nKK 音標：[ˋʌltəmət] -> 主重音在第一個音節 ul，結尾 -mate 要唸輕聲。\n\n常見同義字：\n\nfinal（最後的、最終的，多用於時間或順序上的最後）\nparamount（至高無上的、最重要的，強調地位最高）\nfundamental（最根本的、基礎的，強調核心與根源）",
  "ultimately": "諧音聯想：\n拆解：ultimate（最終的）+ ly。\n\n聯想畫面 1：經過無數次嘗試，最終我們成功了。\n\n聯想畫面 2：這場比賽最終的結果，取決於最後一分鐘的表現。\n\n高效擴充：字根 ultra-（極端、超越），走到極端就是最終點。\nKK 音標：[ˋʌltəmətli] -> 重音在第一個音節，唸起來要有一種塵埃落定的感覺。\n\n常見同義字：\n\nfinally（最後）\n\neventually（最終，強調結果）\n\nin the end（最後）。",
  "ultra": "諧音聯想：\n諧音：歐特拉（超級拉）。\n\n聯想畫面 1：這傢伙是極端主義者，想法超級激進。\n\n聯想畫面 2：他參加了超級馬拉松，體力簡直超越極限。\n\n高效擴充：字根 ultra 表示超過、極端。\nKK 音標：[ˋʌltrə] -> 重音在第一個音節，發音要乾脆。\n\n常見同義字：\n\nextreme（極端的）\n\nsuper（超級的）\n\nexcessive（過分的）。",
  "umbrella": "諧音聯想：\n諧音：「安不來啦」\n\n聯想畫面 1：突然下起暴雨，朋友沒帶雨傘直呼安不來啦，快把我這支借去撐。\n\n聯想畫面 2：公司採用聯合傘狀組織管理，這就是企業內部的 umbrella 綜合體策略。\n\n高效擴充：字首 umbr 代表陰影、遮蔽，用來擋太陽或雨水。\nKK 音標：[əˋmbrɛlə] -> 主重音在第二音節的 bre，發音時要輕快。\n\n常見同義字：\nparasol（遮陽傘，通常較輕巧）\nrain gear（雨具總稱）\nprotection（保護、庇護，抽象用法）",
  "umpire": "諧音聯想：\n諧音：「安派爾」\n\n聯想畫面 1：棒球比賽中，裁判員必須公正地判定好球或壞球，安撫球員的情緒。\n\n聯想畫面 2：當雙方爭執不下時，請第三方公正的仲裁人來主持公道。\n\n高效擴充：常縮寫為 ump，在棒球與網球等運動中是不可或缺的角色。\nKK 音標：[ˋʌm͵paɪɚ] -> 重音在第一音節 um，唸起來像「ㄢˊ派爾」，注意次重音位置。\n\n常見同義字：\n\nreferee（裁判，球類運動如足球籃球常用）\n\njudge（法官或裁判，強調法律或裁決）\n\narbitrator（仲裁人，強調商業或法律糾紛調解）",
  "unabated": "諧音聯想：\n拆解：Un（不）+ Abate（減弱）+ ed。\n\n聯想畫面 1：暴雨不減弱，一直下個不停。\n\n聯想畫面 2：他對工作的熱情不減弱，依然衝勁十足。\n\n高效擴充：abate 意為減弱，加上否定字首 un。\nKK 音標：[͵ʌnəˋbeɪtɪd] -> 重音在第二個音節，發音要平穩。\n\n常見同義字：\n\nrelentless（無情的/不減弱的）\n\npersistent（持續的）。",
  "unable": "諧音聯想：\n拆解：un（不）+ able（能）。\n\n聯想畫面 1：因為受傷，他無法走路。\n\n聯想畫面 2：這項任務太難，他無法勝任。\n\n高效擴充：加上字首 un- 表示否定。\nKK 音標：[əˋnebəl] -> 重音在第二個音節，注意 able 的發音。\n\n常見同義字：\n\nincapable（無能力的）\n\npowerless（無力的）。",
  "unacceptable": "諧音聯想：\n拆解：un（不）+ acceptable（可接受的）。\n\n聯想畫面 1：這種粗魯的行為是無法接受的。\n\n聯想畫面 2：這份品質低劣的產品，客戶完全無法接受。\n\n高效擴充：由 accept（接受）變化而來。\nKK 音標：[͵ʌnækˋsɛptəbəl] -> 重音在第三個音節，唸起來要有強烈的否定感。\n\n常見同義字：\n\nintolerable（無法忍受的）\n\nunsatisfactory（不滿意的）。",
  "unaccountable": "諧音聯想：\n拆解：un（不）+ accountable（可解釋的）。\n\n聯想畫面 1：這件事發生得莫名其妙，完全無法解釋。\n\n聯想畫面 2：他對這筆帳目不負責任，導致無法交代。\n\n高效擴充：accountable 意為需負責的，加上 un- 變成無法負責或無法解釋。\nKK 音標：[͵ʌnəˋkaʊntəbəl] -> 重音在第三個音節，發音要連貫。\n\n常見同義字：\n\ninexplicable（無法解釋的）\n\nmysterious（神秘的）。",
  "unaccustomed": "諧音聯想：\n拆解：un（不）+ accustomed（習慣的）。\n\n聯想畫面 1：我不習慣穿西裝，感覺渾身不對勁。\n\n聯想畫面 2：他對這種寒冷的天氣感到不習慣。\n\n高效擴充：accustom（使習慣）+ ed 變成形容詞。\nKK 音標：[͵ʌnəˋkʌstəmd] -> 重音在第三個音節，注意 ed 的輕音。\n\n常見同義字：\n\nunfamiliar（不熟悉的）\n\nunusual（不尋常的）。",
  "unacknowledged": "拆解：un（不）+ acknowledge（承認）+ ed。\n\n聯想畫面 1：他的貢獻一直被忽視，就像這封信寄出後始終未被答覆一樣。\n\n聯想畫面 2：這項發明雖然偉大，但在當時卻是不被承認的，沒人注意到它的價值。\n\n高效擴充：acknowledge 字根為 ad（去）+ knowledge（知識），即給予認知。\nKK 音標：[͵ʌnəkˋnɑlɪdʒd] -> 重音在第三音節，注意 dʒd 的連音。\n\n常見同義字：\n\nignored（被忽視的）\n\nunrecognized（未被認出的）\n\nunanswered（未被答覆的）。",
  "unafraid": "諧音聯想：\n拆解：un（不）+ afraid（害怕）\n\n聯想畫面 1：小男孩面對大狗依然無畏，他一點都不怕，甚至還想摸摸牠。\n\n聯想畫面 2：面對困難的挑戰，他展現出不害怕的態度，勇往直前。\n\n高效擴充：afraid 是害怕，加了 un- 就是不害怕，非常直觀。\nKK 音標：[͵ʌnəˋfreɪd] -> 重音在第三音節，freid 的發音要堅定。\n\n常見同義字：\nfearless（無畏的）\nbrave（勇敢的）\ndauntless（不屈不撓的）",
  "unanimity": "諧音聯想：\n拆解：un（一）+ anim（心/靈魂）+ ity（名詞字尾）\n\n聯想畫面 1：會議室裡大家終於達成了一致同意，unanimity 的氣氛讓決策順利通過。\n\n聯想畫面 2：在投票中獲得全體一致的支持，這在政治上是極為罕見的 unanimity。\n\n高效擴充：anim 字根代表心或靈魂，如 animal（動物），unanimity 就是大家心連心。\nKK 音標：[͵junəˋnɪməti] -> 重音在第三個音節 ni，唸起來要有一種團結的感覺。\n\n常見同義字：\nconsensus（共識，常用於討論後達成）\nagreement（同意，最基礎的詞）\naccord（一致，較正式）",
  "unanimous": "字根幽默拆解法：un（人數合而為一）＋ anim（同一顆齊心意念）＋ ous（完全同意的樣子）\n\n構造聯想：unanimous 就是大家討論到一半突然「人數合而為一」，懷著「同一顆齊心意念」呈現「完全同意的樣子」沒半張反對票。\n\n記憶畫面：班級表決園遊會攤位要賣珍珠奶茶還是鬆餅時，聽到提案全班瞬間「人數合而為一」發出「同一顆齊心意念」呈現「完全同意的樣子」鼓掌，全票通過全體一致的 (unanimous) 決定！",
  "unarguably": "諧音聯想：\n諧音：安阿給阿不理。\n\n聯想畫面 1：這件事真相大白，安安阿給都不理會反對意見，不容置疑地堅持到底。\n\n聯想畫面 2：法官判決證據確鑿，不容置疑地宣布結果，沒人敢有異議。\n\n高效擴充：un-否定 + argue爭論 + -ably副詞字尾，意指無法爭論。\nKK 音標：[ʌnˋɑrɡjuəbli] -> 重音在第二音節 ar，發音時嘴巴張大。\n\n常見同義字：\n\nindisputably無可爭辯地，undeniably不可否認地，certainly當然地。",
  "unassuming": "拆解：un（不）加上 assuming（自負的、裝腔作勢的）\n\n諧音：「安於速命」\n\n聯想畫面 1：這位億萬富翁穿著極其unassuming，安於平淡樸素的生活，完全不擺架子。\n\n聯想畫面 2：這個小鎮風景unassuming，沒有過度開發的華麗建築，顯得樸實無華。\n\n高效擴充：assume有假裝、自負之意，前面加un否定，就變成謙遜不裝模作樣。\nKK 音標：[͵ʌnəˋsumɪŋ] -> 主重音落在 sum，前面的 un-ə 唸得輕快。\n\n常見同義字：\n\nmodest（謙虛的）\n\nhumble（卑微的、簡樸的）\n\nunpretentious（不矯揉造作的）",
  "unattended": "諧音聯想：\n諧音：安那（un）聽（attend）的（ed）。\n\n聯想畫面 1：行李被丟在機場安檢處無人看管，安檢人員聽不到（un-attend）失主的回應。\n\n聯想畫面 2：路邊停著一輛車，沒人照料，車窗開著，小偷正在觀察。\n\n高效擴充：字首 un- 表示否定，attend 表示照顧，合起來就是沒人照顧。\nKK 音標：[͵ʌnəˋtendɪd] -> 重音在第二音節 tend，發音時嘴巴張開，tend 咬字要清晰。\n\n常見同義字：\n\nneglected（被忽視的，語氣較重）\n\nunwatched（沒人盯著的，較口語）。",
  "unattractiveness": "諧音聯想：\n拆解：un（否定）+ attractive（有吸引力的）+ ness（名詞字尾）。\n\n聯想畫面 1：這間餐廳的 unattractiveness 讓人不想進去，因為裝潢實在太無趣了。\n\n聯想畫面 2：他對這個計畫的 unattractiveness 感到擔憂，覺得完全沒有吸引力。\n\n高效擴充：attractive 是吸引人的，加上 un 變成否定，ness 變成名詞。\nKK 音標：無提供 -> 重音在 trac，注意發音時嘴型要圓潤。\n\n常見同義字：\n\ndullness（無趣，指內容）\n\nugliness（醜陋，指外觀）\n\nunappealingness（不吸引人，指感覺）。",
  "unauthorized": "諧音聯想：\n拆解：un（不）+ authorized（授權的）。\n\n聯想畫面 1：這份文件未經授權，禁止翻閱。\n\n聯想畫面 2：駭客進行了未經許可的存取。\n\n高效擴充：authorize 是授權，加上 un- 表示否定。\nKK 音標：[əˋnɔθɚ͵aɪzd] -> 重音在第二個音節，唸起來要有嚴肅感。\n\n常見同義字：\n\nillegal（非法的）\n\nunlicensed（未獲許可的）。",
  "unaware": "諧音聯想：\n拆解：un（不）+ aware（察覺的）。\n\n聯想畫面 1：他完全沒察覺到後面有人跟蹤。\n\n聯想畫面 2：我對這個計畫的變動毫不知情。\n\n高效擴充：aware 意為意識到的，加上 un- 表示無意識。\nKK 音標：[͵ʌnəˋwɛr] -> 重音在第三個音節，注意最後的 are 發音。\n\n常見同義字：\n\nignorant（無知的）\n\noblivious（未察覺的）。",
  "unbalance": "諧音聯想：\n拆解：un（不）+ balance（平衡）。\n\n聯想畫面 1：這堆積木失去平衡，馬上就要倒了。\n\n聯想畫面 2：巨大的壓力讓他精神失衡，情緒很不穩定。\n\n高效擴充：balance 是平衡，加上 un- 破壞平衡。\nKK 音標：[ənˋbæləns] -> 重音在第二個音節，唸起來要有晃動感。\n\n常見同義字：\n\ninstability（不穩定）\n\ndisorder（混亂）。",
  "unbearable": "拆解：un（不）+ bear（忍受）+ able（能）。\n\n聯想畫面 1：這天氣熱到 unbearable，簡直無法忍受。\n\n聯想畫面 2：這噪音大到讓人 unbearable，必須立刻戴上耳機。\n\n高效擴充：bear 在此作動詞「忍受」解。\nKK 音標：[ʌnˋberəb(ə)l] -> 第二音節重音，bear 發音要清晰，結尾輕快。",
  "unbeatable": "諧音聯想：\n拆解：un（不）+ beat（擊敗）+ able（能）。\n\n聯想畫面 1：這支球隊實力太強，簡直無法被擊敗。\n\n聯想畫面 2：這款遊戲的紀錄無與倫比，沒人能超越。\n\n高效擴充：beat（擊敗）加上 able 變成可擊敗的，再加 un- 否定。\nKK 音標：[͵ʌnˋbitəbəl] -> 重音在第二個音節，唸起來要有氣勢。\n\n常見同義字：\n\ninvincible（無敵的）\n\nunsurpassable（無法超越的）。",
  "unbiased": "諧音聯想：\n諧音：安拜愛死\n\n聯想畫面 1：法官安靜地拜託大家愛死公平正義，所以判決絕對無偏見。\n\n聯想畫面 2：記者報導新聞時，不帶個人情緒，像個機器人一樣客觀公正。\n\n高效擴充：un（不）+ bias（偏見），合起來就是沒有偏見。\nKK 音標：[͵ʌnˋbaɪəst] -> 重音在第二音節，注意 bi 的長母音發音要飽滿。\n\n常見同義字：\n\nimpartial（不偏袒的，常用於正式場合）\n\nfair（公平的，最基礎用法）\n\nobjective（客觀的，強調事實而非個人觀點）",
  "uncannily": "拆解：un（不）＋canny（精明）＋ly。\n\n聯想畫面 1：他竟然能預測未來，這種神秘的能力讓人感到驚異。\n\n聯想畫面 2：這雙眼睛長得跟那幅畫一模一樣，簡直是不尋常的巧合。\n\n高效擴充：canny 原意是精明的，uncanny 則帶有超自然感。\nKK 音標：[ʌnˋkænɪli] -> 重音在第二音節 can，注意 a 的發音。\n\n常見同義字：\n\neerie（怪異的）\n\nstrangely（奇怪地）。",
  "uncanny": "諧音聯想：\n拆解 / 諧音：un（不）+ canny（精明的）。\n\n聯想畫面 1：他竟然能預測未來，這種出奇的準確度實在太離奇了。\n\n聯想畫面 2：深夜森林裡傳來奇怪的聲響，讓人感到一種神秘且可怕的氛圍。\n\n高效擴充：canny 原意為精明，加上否定字首產生反差。\nKK 音標：[ʌnˋkæni] -> 第二音節重音，注意雙 n 的發音。\n\n常見同義字：\n\nEerie（離奇的）\n\nStrange（奇怪的）。",
  "uncared": "拆解：un（不）＋cared（被關心）。\n\n聯想畫面 1：路邊那盆花因為沒人澆水，顯得 uncared，葉子都枯萎了。\n\n聯想畫面 2：被遺棄的小貓眼神中透露出 uncared 的孤獨感。\n\n高效擴充：care 是關心，加上 un- 前綴表示否定。\nKK 音標：無 -> 重音在第二音節，注意 ed 的結尾發音。\n\n常見同義字：\n\nneglected（被忽略的，最常用）\n\nignored（被忽視的）\n\nabandoned（被遺棄的）。",
  "uncertain": "諧音聯想：\n拆解：un（不）+ certain（確定的）\n\n聯想畫面 1：明天天氣如何？氣象局說還不確定，這讓我們的野餐計畫充滿變數。\n\n聯想畫面 2：他對於未來的職涯感到猶豫，這種無把握的感覺讓他很焦慮。\n\n高效擴充：certain 是確定的，加上 un- 就是不確定，是uncertainty 的形容詞。\nKK 音標：[ənˋsɝtən] -> 重音在第二音節，sɝ 的捲舌音要重。\n\n常見同義字：\ndoubtful（懷疑的）\nunsure（沒信心的）\nundetermined（未決定的）",
  "uncertainty": "諧音聯想：\n拆解：un（不）+ certain（確定）+ ty。諧音：安瑟騰替。\n\n聯想畫面 1：未來充滿了 uncertainty，讓人感到迷惘。\n\n聯想畫面 2：面對未知的結果，他心裡充滿了 uncertainty。\n\n高效擴充：certain 是確定的，加上 un- 變成否定。\nKK 音標：[ənˋsɝtənti] -> 重音在 sɝ，發音要重。\n\n常見同義字：\n\ndoubt 懷疑，indecision 猶豫，ambiguity 含糊不清。",
  "unchallenging": "諧音聯想：\n拆解 / 諧音：「un（不）＋ challenging（具挑戰性的）」\n\n聯想畫面 1：這份工作每天只是影印文件，完全沒有挑戰性。\n\n聯想畫面 2：遊戲太簡單過關了，一點挑戰性也沒有覺得很無聊。\n\n高效擴充：challenge 是挑戰，加上 ing 變形容詞，前面加 un 否定，指毫無難度。\nKK 音標：[ʌnˋtʃælɪndʒɪŋ] -> 重音在第二音節 ˋtʃæl，字尾 ing 鼻音要到位。\n\n常見同義字：\n\neasy（簡單的，不費力的）\n\nroutine（例行的，乏味的）\n\nunexciting（不刺激的，平淡的）",
  "uncharacteristic": "諧音聯想：\n拆解：un（不）+ characteristic（典型的）\n\n聯想畫面 1：他今天竟然主動請客，這行為真是不典型，完全不符合他小氣的個性。\n\n聯想畫面 2：這場突如其來的暴風雨在該地區非常罕見，屬於不典型的氣候特徵。\n\n高效擴充：記住 characteristic 是特徵，加上否定字首 un 就是不具備該特徵。\nKK 音標：[͵ʌn͵kærəktəˋrɪstɪk] -> 重音在倒數第三音節，發音節奏較長。\n\n常見同義字：\n\natypical（非典型的，最常用的同義詞）\n\nunusual（不尋常的，範圍更廣）\n\nabnormal（異常的，帶有負面或病理色彩）",
  "uncle": "幽默諧音法：「安可」\n\n發音聯想：uncle [ˋʌŋkəl] 唸起來就像演唱會喊的「安可」。\n\n記憶畫面：多才多藝的叔叔與舅舅 (uncle) 在家庭聚會彈吉他唱歌，全家人拍手大喊「安可」再來一首！",
  "uncommon": "諧音聯想：\n拆解：un 不 + common 常見的。\n\n聯想畫面 1：這種鳥類在台灣很 uncommon，很少見到。\n\n聯想畫面 2：他有著 uncommon 的天賦，非常非凡。\n\n高效擴充：common 是常見的，加上否定字首 un。\nKK 音標：[ʌnˋkɑmən] -> 重音在第二個音節，注意 m 的發音。\n\n常見同義字：\n\nrare（罕見的）\n\nunusual（不尋常的）。",
  "uncomplicated": "諧音聯想：\n拆解 / 諧音：「un（不）＋ complicated（複雜的）」\n\n聯想畫面 1：這道料理的做法非常簡單不複雜，新手也能輕鬆上手。\n\n聯想畫面 2：她喜歡過單純不複雜的生活，沒有人際壓力。\n\n高效擴充：字首 un 表示相反，complicated 來自 complex（複雜），字尾 ated 為形容詞字尾。\nKK 音標：[ʌnˋkɑmplə͵ketɪd] -> 主重音在第二音節 ˋkɑm，副重音在 ke 上。\n\n常見同義字：\n\nsimple（簡單的，樸素的）\n\neasy（容易的，不費力的）\n\nstraightforward（坦率的，簡單明了的）",
  "unconcern": "諧音聯想：\n拆解：un（否定）+ concern（關心）。\n\n聯想畫面 1：面對大火，他竟然表現出 unconcern，若無其事地喝咖啡。\n\n聯想畫面 2：他對考試成績的 unconcern 讓老師很頭痛，完全不擔憂。\n\n高效擴充：concern 是關心，加上 un 變成不關心。\nKK 音標：[͵ʌnkənˋsɝn] -> 重音在最後音節 cern，注意 r 的捲舌音。\n\n常見同義字：\n\nindifference（冷漠，指態度）\n\napathy（無感，指情緒）\n\ndetachment（超然，指距離感）。",
  "uncontrollably": "諧音聯想：\n拆解：un（不）+ control（控制）+ ably（能力地）。\n\n聯想畫面 1：看到好笑的影片，他控制不住地（uncontrollably）大笑起來。\n\n聯想畫面 2：發抖得無法控制（uncontrollably），因為天氣實在太冷了。\n\n高效擴充：常見副詞結尾，拆解後非常直觀。\nKK 音標：[͵ʌnkənˋtroʊləbli] -> 重音在 troʊ，唸起來節奏感強。",
  "unconventional": "諧音聯想：\n拆解 / 諧音：un（不）+ conventional（傳統的）\n\n聯想畫面 1：藝術家穿著睡衣去參加正式晚宴，這種非傳統的打扮讓人印象深刻。\n\n聯想畫面 2：這間公司的辦公室竟然在樹屋裡，做法非常規，不按牌理出牌。\n\n高效擴充：字根 con（一起）+ vent（來），大家一起來的慣例就是傳統，加上 un 就是不遵循傳統。\nKK 音標：[͵ʌnkənˋvɛnʃənəl] -> 重音在第三音節，唸起來節奏感很強。\n\n常見同義字：\n\nunorthodox（非正統的，常用於宗教或思想）\n\noriginal（原創的，強調獨特性）\n\nnovel（新穎的，強調前所未見）",
  "unconvincing": "諧音聯想：\n諧音：安康（un-con）+ 溫馨（vinc）+ 聽（ing）。\n\n聯想畫面 1：推銷員講得口沫橫飛，但內容聽起來一點都不安康溫馨，讓人覺得這根本是詐騙，完全無法信服。\n\n聯想畫面 2：電影裡的壞人解釋犯罪動機，聽起來漏洞百出，觀眾紛紛搖頭表示這劇情太不合理。\n\n高效擴充：字首 un- 表示否定，convince 是說服，字根 vinc 源自拉丁文征服，無法被說服就是令人懷疑。\nKK 音標：[͵ʌnkənˋvɪnsɪŋ] -> 重音在第二音節，唸起來要有被說服不了的無奈感。\n\n常見同義字：\n\ndoubtful（懷疑的，語氣較輕）\n\nimplausible（難以置信的，指情節不合理）\n\nunpersuasive（沒有說服力的，正式用語）。",
  "uncooperative": "諧音聯想：\n拆解 / 諧音：安（un）+ 扣（co）+ 歐（op）+ 瑞（era）+ 踢（tive）。\n\n聯想畫面 1：安安不配合，把扣環踢開，表現得很不合作。\n\n聯想畫面 2：今天天氣不作美，一直下雨，很不配合行程。\n\n高效擴充：字首 un- 否定，cooperative 是合作的。\nKK 音標：[͵ʌnkoʊˋɑpərətɪv] -> 重音在第三音節，tive 發音要輕。",
  "uncover": "字根幽默拆解法：un（動手拿掉）＋ cover（蓋在上面的布蓋）\n\n構造聯想：uncover 就是「動手拿掉」原本「蓋在上面的布蓋」，讓藏在底下的驚喜與真相一口氣顯露出來。\n\n記憶畫面：魔術師把紅色天鵝絨布罩住桌上鳥籠兩秒後，請小觀眾走上台前親自「動手拿掉」這塊「蓋在上面的布蓋」，瞬間揭開 (uncover) 一籃彩色汽球！",
  "undemanding": "諧音聯想：\n拆解 / 諧音：「un（不）＋ demanding（嚴格要求的）」\n\n聯想畫面 1：這個老闆對員工要求不高，工作起來輕鬆愉快。\n\n聯想畫面 2：這項任務十分簡單，不需要花費太多心力去應付苛刻條件。\n\n高效擴充：demand 是要求，demanding 是要求極高的，加上 un 就變成不苛求的。\nKK 音標：[͵ʌndɪˋmændɪŋ] -> 主重音在第三音節 ˋmænd，前面 un 有副重音。\nN/A\n\n常見同義字：\n\neasygoing（隨和的，好相處的）\n\nlenient（寬容的，不嚴格的）\n\naccommodating（隨和的，樂於助人的）",
  "under": "幽默諧音法：「俺躲」\n\n發音聯想：under [ˋʌndɚ] 唸起來像「俺躲」在桌子底下。\n\n記憶畫面：玩捉迷藏時「俺躲」在書桌下面 (under)，蓋著桌巾誰也找不到！",
  "underestimate": "諧音聯想：\n拆解 / 諧音：安德魯估得死太慢了\n\n諧音：「安德魯估得死太慢了」\n\n聯想畫面 1：安德魯太輕敵了，嚴重低估了對手的實力結果慘遭滑鐵盧。\n\n聯想畫面 2：老闆對這季銷售量的估計不足，導致貨物嚴重缺貨挨罵。\n\n高效擴充：由 under (在...下方/不足) 加上 estimate (估計) 組合而成。\nKK 音標：[ˋʌndɚˋɛstə͵met] -> 主重音在第一個音節 un 和第三個音節 es。\n\n常見同義字：\n\nundervalue（低估價值、看輕，常用於資產或重要性評估）\nminimize（將...減到最小或輕視其嚴重性）\ndisparage（貶低、輕蔑，語氣較強指言語上的看不起）",
  "undergo": "字根幽默拆解法：under（扛在底下面對）＋ go（繼續走過去）\n\n構造聯想：undergo 就是雖然挑戰沉甸甸地壓在頭頂，依然「扛在底下面對」並且咬緊牙關「繼續走過去」。\n\n記憶畫面：學烘焙前每天得凌晨四點起床搓麵團並站在高溫烤箱旁，「扛在底下面對」辛苦練習仍微笑「繼續走過去」，只有親自經歷 (undergo) 過才嚐得出成就甜味！",
  "undergraduate": "諧音聯想：\n諧音：「安德勒格瑞得」\n\n聯想畫面 1：大一到大四的大學本科生正忙著準備期末專題與畢業論文。\n\n聯想畫面 2：圖書館裡四處可見大學肄業生認真K書的身影。\n\n高效擴充：由 under（在下面）加 graduate（畢業生）組成，意指尚未畢業的大學生。\nKK 音標：[͵ʌndɚˋɡrædʒəwət] -> 主重音在第三音節 gra，唸起來像「安德˙ㄜˊˋ格拉ㄐㄨㄚˋㄨ特」。\n\n常見同義字：\n\ncollege student（大學生，最口語常用）\n\nuniversity student（大學生，英式或正式常用）\n\ngraduate student（研究生，與本字相對）",
  "underground": "諧音聯想：\n拆解 / 諧音：「under（在下面）＋ ground（地面）」\n\n聯想畫面 1：地下街藏著許多美食，大家都在地下道匆忙趕著搭地鐵。\n\n聯想畫面 2：這個地下抵抗組織在暗中秘密活動，策劃對抗不公的體制。\n\n高效擴充：由介系詞 under 與名詞 ground 組合而成的複合字。\nKK 音標：[ˋʌndɚ͵ɡraʊnd] -> 主重音在最前面的 un，念起來乾脆有力。\n\n常見同義字：\nsubway（地鐵，主要指美式用法）\nmetro（地鐵，歐洲或都會區常用）\nsecret（秘密的，形容隱蔽狀態）",
  "undergrowth": "諧音聯想：\n拆解 / 諧音：底下生長\n\n諧音：「安得個肉服」\n\n聯想畫面 1：熱帶雨林的大樹底下生長著濃密的矮樹叢與林下植物。\n\n聯想畫面 2：動物長在長毛底下的濃密絨毛，就像大樹底下的下層植物一樣保暖。\n\n高效擴充：由 under（在...底下）加上 growth（生長、植物）組合而成。\nKK 音標：[ˋʌndərɡroʊθ] -> 第一音節un-重音，th發無聲咬舌音。\n\n常見同義字：\n\nunderbrush（林下灌木，同義常用）\n\nbrushwood（柴薪、灌木叢）\n\nunderstory（林下層植物）",
  "underline": "諧音聯想：\n諧音：「安德賴恩」\n\n聯想畫面 1：老師上課時要求我們在重點單字下面畫線，方便複習時一眼看出。\n\n聯想畫面 2：講者在簡報中特別強調某個數據，用來凸顯其重要性。\n\n高效擴充：由 under（下面）加上 line（線）組成，字面直譯就是在下面畫線。\nKK 音標：[ˋʌndɚ͵laɪn] -> 主重音在第一音節 un，唸起來像「ㄢˊ得˙ㄜˊ賴恩」。\n\n常見同義字：\n\nstress（強調，抽象語意）\n\nemphasize（強調，較正式）\n\nhighlight（用螢光筆標示，視覺上突出）",
  "undermine": "諧音聯想：\n拆解 / 諧音：under（在底下）+ mine（地雷、挖礦）\n\n拆解 / 諧音：「安得買因」\n\n聯想畫面 1：敵軍在城堡底下埋地雷，暗中破壞城堡的基礎結構。\n\n聯想畫面 2：同事在背後說壞話，逐漸削弱了他在主管心中的良好形象。\n\n高效擴充：字面意思是「在下方挖礦」，引申為從底部破壞。\nKK 音標：[ˋʌndɚ͵maɪn] -> 主重音在第一個音節 un，次重音在 mine。\n\n常見同義字：\n\nweaken（削弱，使變弱的通用詞）\n\nsabotage（蓄意破壞，常指破壞設備或計畫）\n\nimpair（損害、削弱，多用於健康、功能或能力）",
  "underneath": "諧音聯想：\n諧音：「安德尼斯」\n\n聯想畫面 1：小貓咪因為害怕打雷，躲在沙發底下不敢出來。\n\n聯想畫面 2：華麗的外表底下，其實隱藏著許多不為人知的辛酸與壓力。\n\n高效擴充：由 under（下面）結合 neath（底部）而成，比 under 更具包覆感。\nKK 音標：[͵ʌndɚˋniθ] -> 主重音在第二音節 neath，唸起來像「ㄢˊ得˙ㄜˊ呢ㄙˋ」，注意 th 的咬舌音。\n\n常見同義字：\n\nbeneath（在……下方，較為文學或正式）\n\nunder（在……下面，最基礎常見）\n\nbelow（在……之下，位置較低）",
  "underpass": "諧音聯想：\n諧音：「安德怕死」\n\n聯想畫面 1：安德烈因為很怕過馬路被車撞，所以總是乖乖走地下道與下穿通道。\n\n聯想畫面 2：騎機車遇到大雷雨時，大家紛紛躲進路口的高架橋下或地下人行道避雨。\n\n高效擴充：under（在下方）加上 pass（通過），組合起來就是地下道。\nKK 音標：[ˋʌndɚ͵pæs] -> 重音在第一音節 UN，pæs 是次重音。\n\n常見同義字：\n\nsubway（地鐵、地下道，美式常用字）\n\ntunnel（隧道、地道，範圍較大或穿山而過）\n\noverpass（高架橋、天橋，與 underpass 相反的概念）",
  "underrated": "拆解：under（在下）+ rated（評價）。\n\n聯想畫面 1：這部電影評價被低估了，其實很好看。\n\n聯想畫面 2：他的才華一直被低估，沒人發現他的努力。\n\n高效擴充：under- 字首表示不足。\nKK 音標：[͵ʌndəˋreɪtɪd] -> 重音在第三音節 ra。\n\n常見同義字：\n\nunderestimated（低估的）\n\nundervalued（價值被低估的）。",
  "understand": "字根幽默拆解法：under（在…之下）＋ stand（站立）\n\n構造聯想：understand 就是設身處地「站」在對方的立場「之下」體會，代表理解、明白。\n\n記憶畫面：只要願意「站」在對方的角度「之下」傾聽，就能完全理解與明白 (understand) 彼此的想法！",
  "understandable": "諧音聯想：\n拆解 / 諧音：understand（理解）加上 able（能夠），安得死登打波代表能夠被大家所理解。\n\n聯想畫面 1：他因為火車誤點而遲到，這個理由在聽了之後讓人完全可以理解。\n\n聯想畫面 2：這本科學普及讀物寫得很淺顯，裡面的概念都是一般人能懂的。\n\n高效擴充：由動詞 understand 轉變為形容詞，字尾 able 表示具備某種能力或性質。\nKK 音標：[͵ʌndɚˋstændəbəl] -> 主重音落在第參音節 stænd，唸起來節奏分明。\n\n常見同義字：\n\ncomprehensible（可理解的，較正式且範圍廣）\nintelligible（清晰易懂的，多指語言或文字）\nlogical（合乎邏輯的，指推論合理）",
  "understanding": "諧音聯想：\n拆解 / 諧音：under（在下面）+ stand（站）+ ing\n\n聯想畫面 1：我站在你的立場（under/below your perspective），才能真正理解你的感受，這就是諒解。\n\n聯想畫面 2：我們之間有個默契（understanding），不用多說，對方就懂我的意思。\n\n高效擴充：字面意思是站在下面支撐，引申為理解對方的處境。\nKK 音標：[͵ʌndərˋstændɪŋ] -> 重音在第二音節 stænd，唸起來要有堅定的感覺。\n\n常見同義字：\nComprehension（理解，較正式，指對知識的掌握）\nAgreement（協議，指達成共識）\nEmpathy（同理心，指深層的諒解與共感）",
  "understatement": "諧音聯想：\n拆解 / 諧音：under（在下面）+ statement（陳述）\n\n聯想畫面 1：明明考了滿分，卻說只是運氣好，這種保守的陳述是一種謙虛的淡化。\n\n聯想畫面 2：面對巨大的災難，政府卻輕描淡寫地說沒事，這種不充分的陳述引發民眾不滿。\n\n高效擴充：把話壓在下面講，就是說得比實際情況輕，即淡化。\nKK 音標：[ˋʌndɚ͵stetmənt] -> 重音在第一個音節，注意 stet 的長母音。\n\n常見同義字：\n\nunderplay（輕描淡寫，動詞用法）\n\ndownplay（貶低、輕視，強調刻意降低重要性）\n\nrestraint（克制，指說話保留）",
  "undertake": "諧音聯想：\n拆解 / 諧音：under（在下面）+ take（拿）\n\n拆解 / 諧音：「安得泰客」\n\n聯想畫面 1：新上任的經理勇敢承擔這個困難重重的新專案。\n\n聯想畫面 2：工程團隊開始著手進行這項大型的跨海大橋建設。\n\n高效擴充：三態為 undertake、undertook、undertaken。\nKK 音標：[ˋʌndɚ͵tek] -> 主重音在第一個音節 un，次重音在 take。\n\n常見同義字：\n\nbegin（開始，最通俗的動詞）\n\nattempt（嘗試、企圖，強調著手去做一件事）\n\ncontract（承包，商業上承擔工程或工作）",
  "undertaking": "諧音聯想：\n拆解 / 諧音：安德（under）＋ 貼金（taking）\n\n諧音：安德貼金\n\n聯想畫面 1：安德接下了一個艱鉅的任務，為了完成它，他甚至把自己的積蓄都貼進去，這就是一種承擔與企業行為。\n\n聯想畫面 2：在喪葬業（undertaking）工作的人，總是默默承擔著送別生命的重責大任。\n\n高效擴充：under（在下面）＋ take（拿），在下面扛著任務，就是承擔或從事的意思。\nKK 音標：[͵ʌndərˋteɪkɪŋ] -> 重音在第三個音節，注意前綴 under 的輕讀與後綴 taking 的重讀。\n\n常見同義字：\n\ntask（任務，指具體的工作項目）\n\nenterprise（企業或冒險性的事業）\n\ncommitment（承諾，強調責任感）",
  "undertook": "諧音聯想：\n拆解 / 諧音：安德（under）＋ 脫褲（took）\n\n聯想畫面 1：安德為了完成艱鉅的任務，竟然當眾脫褲子展現決心，這就是他承擔責任的方式。\n\n聯想畫面 2：他勇敢地承擔了這份工作，就像脫褲子一樣乾脆，直接著手開始執行計畫。\n\n高效擴充：undertake 的過去式，under（在下面）加上 take（拿），意指把責任扛在下面承擔起來。\nKK 音標：[͵ʌndərˋtʊk] -> 重音在第二音節 took，發音時注意短母音 u 的短促感。",
  "underuse": "諧音聯想：\n拆解 / 諧音：under（在下面）+ use（使用）\n\n聯想畫面 1：這台昂貴的機器一直被放在倉庫底下（under）沒人去用，真是嚴重的未充分利用（underuse）。\n\n聯想畫面 2：公司購買的軟體授權因為員工都不會用，導致長期處於 underuse 的狀態，浪費了預算。\n\n高效擴充：字首 under- 表示不足或在下方，與 overuse（過度使用）剛好相反。\nKK 音標：[͵ʌndərˋjus] -> 重音在最後的 use，發音時注意 s 要發清音。\n\n常見同義字：\n\nunderutilization（較正式的商業用語，指未充分利用資源）\n\nneglect（忽視，指完全不用或疏於照顧）\n\nmisuse（誤用，指用錯方法而非用得少）",
  "underway": "諧音聯想：\n諧音：安的威\n\n聯想畫面 1：工程師說這項安的威（安全威脅）排除計畫正在進行中，不能中斷。\n\n聯想畫面 2：奧運比賽正在進行中，選手們在跑道上全力衝刺。\n\n高效擴充：under（在...之下）+ way（路），在路上走著，就是正在進行。\nKK 音標：[͵ʌndɚˋwe] -> 重音在第二音節，way 要唸得響亮。\n\n常見同義字：\n\nin progress（進行中，最常用的片語）\n\nongoing（持續進行的，形容詞用法）\n\nstarted（已開始的，強調起點）",
  "underwear": "諧音聯想：\n拆解 / 諧音：「under（在裡面）＋ wear（穿著）」\n\n聯想畫面 1：每天洗完澡第一件穿上的就是貼身內衣褲。\n\n聯想畫面 2：晾在陽台的內衣不小心被風吹掉，掉到隔壁鄰居的遮雨棚上。\n\n高效擴充：under 加上表衣物的 wear，指穿在最內層的衣物。\nKK 音標：[ˋʌndɚ͵wɛr] -> 主重音在最前面的 un，wɛr 要念長音。\n\n常見同義字：\nintimates（貼身內衣褲，較柔和的說法）\napparel（衣服、服飾的總稱）\nclothing（日常衣物）",
  "underwriting": "諧音聯想：\n拆解 / 諧音：under（在底下）加 writing（寫字）。\n\n諧音：「安得瑞，寫保單！」\n\n聯想畫面 1：核保人員在合約底下簽名蓋章，進行保險承保（underwriting）的風險評估。\n\n聯想畫面 2：金融機構主管仔細審核貸款案件，進行證券包銷或貸款審批（underwriting）。\n\n高效擴充：源自古早英國保險業者在保單下方簽名以承擔風險的做法。\nKK 音標：[ˋʌndɚ͵raɪtɪŋ] -> 重音在第一個音節 ˋʌndɚ，raɪtɪŋ 正常發音。\n\n常見同義字：\n\ninsurance assessment（保險評估）\n\nloan approval（貸款審批）\n\nfinancial backing（財務背書）",
  "undetermined": "諧音聯想：\n拆解：un 不 + determine 決定 + ed。\n\n聯想畫面 1：計畫的時間還 undetermined，還沒確定下來。\n\n聯想畫面 2：他是一個 undetermined 的人，做事優柔寡斷。\n\n高效擴充：determine 是決定，加上否定字首 un。\nKK 音標：[͵ʌndɪˋtɝmɪnd] -> 重音在第三個音節，注意 r 的捲舌音。\n\n常見同義字：\n\nuncertain（不確定的）\n\nindecisive（優柔寡斷的）。",
  "undisturbed": "字根幽默拆解法：un（完全沒有）＋ disturb（跑來敲門打擾）＋ ed（保持靜靜安好）\n\n構造聯想：undisturbed 就是整天在秘密書房裡「完全沒有」被外頭雜事「跑來敲門打擾」，讓專注與平靜一直「保持靜靜安好」。\n\n記憶畫面：週日午後把手機調靜音窩在窗邊看最喜歡的小說，兩小時「完全沒有」人「跑來敲門打擾」一切都「保持靜靜安好」，享受了一段珍貴不受打擾的安靜的 (undisturbed) 時光！",
  "undo": "諧音聯想：\n拆解 / 諧音：un（反向）+ do（做）\n\n拆解 / 諧音：「安搭」\n\n聯想畫面 1：電腦修圖軟體按下了 Ctrl 加 Z，成功撤銷還原上一步動作。\n\n聯想畫面 2：登山客到達營地後，快速解開背包的扣環與鞋帶。\n\n高效擴充：電腦軟體中常見的「復原（Undo）」功能就是這個字。\nKK 音標：[ənˋdu] -> 主重音在第二個音節 do，發長 u 音。\n\n常見同義字：\n\ncancel（取消、廢除預約或計畫）\n\nreverse（倒轉、反轉，恢復原狀）\n\nuntie（解開繩子或結）",
  "undoubtedly": "諧音聯想：\n諧音：「安得堡，得力」\n\n聯想畫面 1：這座城堡蓋得非常穩固安穩，毫無疑問地肯定能抵擋外敵入侵。\n\n聯想畫面 2：他平時努力練習，這次考試毫無疑問地拿下了全校第一名。\n\n高效擴充：由 doubt（懷疑）加 un（不）與 edly 結合，意指不容懷疑地。\nKK 音標：[ənˋdaʊtɪdli] -> 主重音落在第二音節 daʊt，前後音節輕讀。\n\n常見同義字：\ncertainly（必定、當然）\nsurely（確實地）\ndefinitely（明確地、肯定地）",
  "undress": "拆解：un（不/反）+ dress（穿衣）。\n\n聯想畫面 1：回到家把外衣脫掉，undress 讓身體放鬆。\n\n聯想畫面 2：醫生準備幫病人換藥，必須先 undress 傷口上的紗布。\n\n高效擴充：un 作為否定字首，表示動作的反向。\nKK 音標：[ʌnˋdres] -> 重音在第二音節，dres 發音要清晰。\n\n常見同義字：\n\nstrip（脫去，較強烈）\n\ntake off（脫掉，最常用）\n\ndisrobe（脫掉衣服，較正式）。",
  "uneasy": "諧音聯想：\n諧音：安以（不）\n\n聯想畫面 1：安以軒心裡覺得不安，因為她總覺得後面有人在跟蹤她。\n\n聯想畫面 2：坐在搖晃的椅子上，感覺非常不安穩，讓人坐立難安。\n\n高效擴充：字首 un 代表否定，easy 是容易的，不覺得容易就是心裡有負擔、不安。\nKK 音標：[ʌnˋizi] -> 重音在第二音節 ea，發長音 i，唸起來要有一種懸著心的感覺。\n\n常見同義字：\nanxious（焦慮的，帶有強烈擔憂情緒）\nworried（擔心的，最普遍的心理狀態）\nuncomfortable（不舒服的，指身體或心理的侷促）",
  "unemotional": "諧音聯想：\n拆解：un（不）+ emotional（情緒化的）。\n\n聯想畫面 1：他像個機器人一樣，面對任何災難都保持冷靜，完全是一個不易動感情的人。\n\n聯想畫面 2：在法庭上，證人冷漠地陳述事實，展現出完全無動於衷的態度。\n\n高效擴充：字首 un 表示否定，加上 emotional 構成形容詞。\nKK 音標：[͵ʌnɪˋmoʊʃənl] -> 重音在 mo 上，發音時要強調情緒的轉折。\n\n常見同義字：\n\nCold（冷漠的，指性格）\n\nDetached（超然的，指客觀態度）\n\nIndifferent（無關緊要的，指不在乎）。",
  "unemployed": "拆解：un（不）+ employed（被僱用）。\n\n聯想畫面 1：一個人坐在公園長椅上，手裡拿著報紙尋找工作，因為他目前處於失業狀態。\n\n聯想畫面 2：工廠裡有一排機器被蓋上帆布，因為訂單減少，這些機器處於閒置狀態。\n\n高效擴充：由動詞 employ 變化而來，加上否定字首 un。\nKK 音標：[͵ʌnɪmˋplɔɪd] -> 重音在第三個音節，發音時注意最後的 d 結尾。\n\n常見同義字：\nJobless（失業的，較口語）\nOut of work（失業的，常用片語）\nIdle（閒置的，指物）",
  "unemployment": "諧音聯想：\n拆解 / 諧音：安妮不補賣夢想\n\n諧音：「安妮不補賣夢想」\n\n聯想畫面 1：安妮失業後找不到工作，整天待在家裡不再盲目賣夢想。\n\n聯想畫面 2：政府公布了本季的失業率與失業人數，呼籲民眾重視經濟不景氣。\n\n高效擴充：由否定字首 un- 加上 employ (雇用) 再加上名詞字尾 -ment。\nKK 音標：[͵ʌnɪmˋplɔɪmənt] -> 主重音在第三個音節 ploy，前面 un- 為次重音。\n\n常見同義字：\n\njoblessness（失業狀態，較直接描述沒有工作的客觀事實）\nlayoff（指因為公司裁員而導致的暫時性失業現象）\ndole（失業救濟金，常在英式英文片語中搭配使用）",
  "unethical": "諧音聯想：\n拆解 / 諧音：安那死卡。\n\n聯想畫面 1：這種不道德的行為，簡直是安那死卡（讓人死掉的卡片），太糟糕了。\n\n聯想畫面 2：他不遵守職業道德，被公司開除了。\n\n高效擴充：Un（不）+ Ethical（道德的），合起來就是不道德。\nKK 音標：[ʌnˋeθɪkl] -> 重音在第二個音節，發音時 th 要輕咬舌尖。\n\n常見同義字：\n\nImmoral（不道德的，範圍更廣）\n\nDishonest（不誠實的）。",
  "uneven": "諧音聯想：\n拆解：un（不）+ even（平坦/偶數）\n\n聯想畫面 1：這條路鋪得坑坑洞洞，一點都不平坦，走起來腳很痛。\n\n聯想畫面 2：兩隊實力太懸殊，比賽變成一邊倒的局面，這是不公平的競爭。\n\n高效擴充：even 有平坦的意思，也有偶數的意思，加上 un 就是不平坦或奇數。\nKK 音標：[ʌnˋiv(ə)n] -> 重音在第二音節，唸起來要有起伏感。\n\n常見同義字：\nrough（粗糙的，表面不平）\nunequal（不相等的，數量或權利）\nodd（奇數的，與 even 相對）",
  "unexacting": "諧音聯想：\n拆解 / 諧音：「un（不）＋ exacting（嚴格挑剔的）」\n\n聯想畫面 1：房東對房客要求很寬容，房間只要大致乾淨就行。\n\n聯想畫面 2：她是一個很好取悅、不挑剔的人，送什麼禮物都開心。\n\n高效擴充：exacting 來自 exact（精確、嚴格），字首 un 代表否定，合起來指不嚴格、容易滿足。\nKK 音標：[͵ʌnɪˋzæktɪŋ] -> 重音落在第三音節 ˋzækt 上，唸起來要分明。\n\n常見同義字：\n\ntolerant（寬容的，容忍的）\n\nundemanding（不苛求的，要求不高的）\n\nforgiving（寬恕的，不計較的）",
  "unexcitable": "諧音聯想：\n拆解 / 諧音：安以可賽特波\n\n聯想畫面 1：他是一個不容易激動的人，就算大家都在賽特波（賽車）場上大吼大叫，他依然安靜如水。\n\n聯想畫面 2：面對突發新聞，他冷靜分析，完全不會像其他人一樣情緒起伏劇烈。\n\n高效擴充：字首 un-（不）+ excite（激動），字尾 -able（能...的），意指不能被激動的。\nKK 音標：無 -> 重音在第二音節，發音時注意輕重音的節奏感。\n\n常見同義字：\ncalm（平靜，最常見的描述）\ncomposed（鎮定，強調情緒控制）\nplacid（溫和的，強調性格平靜）",
  "unexpected": "字根幽默拆解法：un（完全沒有）＋ expect（事先猜想預料）＋ ed（已經來到眼前）\n\n構造聯想：unexpected 就是心中「完全沒有」「事先猜想預料」會登場，卻突然「已經來到眼前」的小驚喜。\n\n記憶畫面：原本以為只是平凡的補課週五，推開門卻看見十年不見的國小同學捧著蛋糕出現，「完全沒有」「事先猜想預料」的畫面居然「已經來到眼前」，真是太出乎意料的 (unexpected) 重逢！",
  "unexplainable": "諧音聯想：\n拆解：un 不 + explain 解釋 + able 能。\n\n聯想畫面 1：這件事的發生原因 unexplainable，科學也無法給出答案。\n\n聯想畫面 2：他 unexplainable 的情緒轉變，讓身邊的人都感到困惑。\n\n高效擴充：由 explain 動詞加上否定字首 un 和形容詞字尾 able 組成。\nKK 音標：無 -> 重音在第二個音節，唸法與 explainable 類似。\n\n常見同義字：\n\ninexplicable（較正式）\n\nmysterious（神秘的）。",
  "unfair": "諧音聯想：\n諧音：安飛兒\n\n聯想畫面 1：安飛兒在比賽中被裁判刻意扣分，她大喊這太不公平了。\n\n聯想畫面 2：分蛋糕時，弟弟拿到一大塊，我只有一小塊，這明顯是不公正的分配。\n\n高效擴充：un（不）+ fair（公平的），反義詞直接組合。\nKK 音標：[ənˋfɛr] -> 重音在第二音節，fɛr 的母音要發得扁平。\n\n常見同義字：\n\nunjust（不公正的，較正式，常用於法律）\n\nbiased（有偏見的，反義詞）\n\nunequal（不平等的，強調數量或地位）",
  "unfairness": "諧音聯想：\n拆解：un（不）+ fair（公平）+ ness（名詞字尾）\n\n聯想畫面 1：比賽裁判明顯偏袒一方，這種不公平的判決讓觀眾大喊抗議。\n\n聯想畫面 2：老闆只給特定員工加薪，這種不正當的行為引發全公司不滿。\n\n高效擴充：fair 是公平，un- 就是不公平，非常直觀的組合。\nKK 音標：[͵ʌnˋfernəs] -> 重音在第二音節，fair 的發音要拉長，強調不公平的感覺。\n\n常見同義字：\ninjustice（不公正，較正式）\npartiality（偏袒）\ninequity（不平等）",
  "unfamiliar": "諧音聯想：\n拆解：un 不 + familiar 熟悉的。\n\n聯想畫面 1：這條路對我來說很 unfamiliar，我從來沒走過。\n\n聯想畫面 2：他來到一個 unfamiliar 的環境，感到有些緊張。\n\n高效擴充：familiar 是熟悉的，加上否定字首 un。\nKK 音標：[͵ʌnfəˋmɪliər] -> 重音在第三個音節，注意 li 的發音。\n\n常見同義字：\n\nstrange（奇怪的，陌生的）\n\nunknown（未知的）。",
  "unfashionable": "諧音聯想：\n拆解：un（不）＋fashion（時尚）＋able（能）。\n\n聯想畫面 1：這件外套完全不時尚，穿出去顯得非常過時。\n\n聯想畫面 2：他不喜歡追逐潮流，總是穿著過時的衣服。\n\n高效擴充：fashionable 的反義詞。\nKK 音標：[ʌnˋfæʃnəbl] -> 重音在第二音節，注意中間的 sh 氣音。",
  "unfasten": "諧音聯想：\n諧音：「安發死疼」\n\n聯想畫面 1：安全帶扣得太緊安發死疼（unfasten），趕快把它解開、鬆開才舒服。\n\n聯想畫面 2：回到家把鞋帶和外套鈕扣通通解開、放鬆（unfasten），享受居家自由時光。\n\n高效擴充：字首 un 表示相反動作，fasten 是扣緊、固定，組合起來就是解開、鬆開。\nKK 音標：[ʌnˋfæs(ə)n] -> 中間的 fas 發短音æ，t 常常不發音或輕發音。\n\n常見同義字：\nloosen（鬆開，強調使不緊繃）\nundo（解開，常用於衣服或繩索）\ndetach（分離、拆卸，較正式）",
  "unfavourable": "諧音聯想：\n拆解：un（不）+ favourable（贊同的、有利的）\n\n聯想畫面 1：天氣預報顯示有暴風雨，這對我們的戶外婚禮是非常不利的條件。\n\n聯想畫面 2：董事會對這項投資案持反對態度，給出了不贊同的評價。\n\n高效擴充：favour 是恩惠、支持，favourable 是有利的，un- 則為否定。\nKK 音標：[ʌnˋfeɪvərəbl] -> 第二音節 fei 重音，發音像飛，後綴輕讀。\n\n常見同義字：\nadverse（指有害的、不利的）\nunfavorable（美式拼法，注意拼寫）\nnegative（指負面的、反對的）",
  "unfavourably": "諧音聯想：\n拆解：un（不）+ favour（喜愛）+ ably（地）。諧音：安飛佛瑞布里。\n\n聯想畫面 1：天氣狀況不利於飛行，飛機無法起飛。\n\n聯想畫面 2：評審對他的表現評價 unfavourably，讓他感到很挫折。\n\n高效擴充：favour 是喜愛，un- 表示否定。\nKK 音標：[ʌnˋfeɪvərəbli] -> 重音在 fei，發音要飽滿。\n\n常見同義字：\n\nadversely 不利地，negatively 負面地，poorly 差勁地。",
  "unfilled": "諧音聯想：\n拆解：un（不）+ filled（填滿的）。\n\n聯想畫面 1：這張訂單因為缺貨，至今仍是未交付狀態。\n\n聯想畫面 2：公司經理職位空缺已久，至今尚未填補。\n\n高效擴充：un- 為否定字首，filled 是 fill 的過去分詞當形容詞用。\nKK 音標：[ʌnˋfɪld] -> 重音在第二個音節，注意 f 的摩擦音。\n\n常見同義字：\n\nempty（空的，直接描述）\n\nvacant（空缺的，多指職位或房間）\n\nunmet（未滿足的，多指需求）。",
  "unfit": "諧音聯想：\n諧音：安非特（安非他命特徵）\n\n聯想畫面 1：這名運動員因為長期熬夜，身體狀況極差，被教練判定為不適合參加比賽。\n\n聯想畫面 2：這件衣服尺寸太小，穿起來完全不合身，顯得非常不適宜。\n\n高效擴充：字首 un- 表示否定，fit 表示合適，合起來就是不合適。\nKK 音標：[ʌnˋfɪt] -> 重音在第二音節，發音時注意短母音 i 的清脆感。\n\n常見同義字：\nunsuitable（不適合的，較通用）\ninappropriate（不恰當的，強調社交禮儀）\nincompetent（無能的，強調工作能力不足）",
  "unfold": "諧音聯想：\n拆解 / 諧音：un（打開）+ fold（摺疊）\n\n拆解 / 諧音：「安佛得」\n\n聯想畫面 1：魔術師在觀眾面前慢慢展開神祕的地圖。\n\n聯想畫面 2：隨著劇情發展，故事的真相在眼前逐漸明朗。\n\n高效擴充：fold 是摺疊，加上否定字首 un 代表把摺疊的打開。\nKK 音標：[ənˋfold] -> 主重音在第二個音節 fold，發雙母音 o。\n\n常見同義字：\n\ndevelop（發展、展開，多用於事件進展）\n\nopen（打開，最基礎的動作動詞）\n\nunroll（展開紙捲或布捲）",
  "unforeseen": "諧音聯想：\n拆解 / 諧音：un（不）+ fore（前）+ seen（看見）\n\n聯想畫面 1：原本晴天卻突然下大雨，這場未預見到的暴雨讓活動被迫取消。\n\n聯想畫面 2：計畫中出現了意料之外的變數，導致進度嚴重落後。\n\n高效擴充：fore 代表前，seen 是看，前面沒看到就是無法預料。\nKK 音標：[͵ʌnfɔrˋsin] -> 重音在第三音節，注意 sin 的長母音。\n\n常見同義字：\n\nunexpected（意外的，最常見）\n\nunanticipated（未預料到的，較正式）\n\nsudden（突然的，強調時間點）",
  "unfortunate": "諧音聯想：\n拆解 / 諧音：安，佛取那特（unfortunate）\n\n聯想畫面 1：安，你佛取那特（unfortunate）嗎？如果一個人運氣很差，連佛祖都取不到那特（特權），那真是太不幸了。\n\n聯想畫面 2：在尷尬的場合說錯話，那種令人遺憾且倒楣的感覺，就是 unfortunate。\n\n高效擴充：un- 否定，fortunate 幸運的，合起來就是不幸運的。\nKK 音標：[ʌnˋfɔrtʃənət] -> 重音在第二音節，注意 for 的發音要捲舌，結尾的 nat 要輕讀。\n\n常見同義字：\n\nunlucky（倒楣的，最常用的口語）\n\nregrettable（令人遺憾的，強調後悔感）\n\nill-fated（命運不佳的，較文學的說法）",
  "unfortunately": "諧音聯想：\n拆解 / 諧音：un（不）+ fortunate（幸運的）+ ly\n\n聯想畫面 1：不幸地，我出門忘了帶傘，結果淋成了落湯雞。\n\n聯想畫面 2：遺憾地，我們這次沒有拿到冠軍，但大家已經盡力了。\n\n高效擴充：fortunate 是幸運，加上 un 變不幸，結尾 ly 變副詞。\nKK 音標：[ənˋfɔrtʃənətli] -> 重音在第二音節，唸起來要有一種嘆氣的節奏感。\n\n常見同義字：\n\nunluckily（運氣不好地，較口語）\n\nregrettably（令人遺憾地，較正式）\n\nalas（哎呀，感嘆詞，表達遺憾）",
  "unfounded": "拆解：不（un）＋有根據（founded）。\n\n聯想畫面 1：這個謠言完全沒有事實根據，簡直是胡說八道。\n\n聯想畫面 2：法官駁回了這個無根據的指控。\n\n高效擴充：found 在此指建立基礎，unfounded 就是沒有地基的。\nKK 音標：[ʌnˋfaʊndɪd] -> 重音在第二個音節，結尾 ed 發 id 音。\n\n常見同義字：\n\ngroundless（無根據的，較正式）\n\nbaseless（無基礎的，強調無事實）。",
  "unfurnished": "諧音聯想：\n拆解：un（不）+ furnished（配備傢俱的）。\n\n聯想畫面 1：這間租屋完全 unfurnished，房東只給了四面牆。\n\n聯想畫面 2：搬進 unfurnished 的新家，第一件事就是去買床。\n\n高效擴充：furnish 原意為提供設備，加 un 變否定。\nKK 音標：[ʌnˋfɝnɪʃt] -> 重音在第二音節，注意 ur 的捲舌音。\n\n常見同義字：\n\nempty（空的）\n\nbare（赤裸的，指沒傢俱）。",
  "unhappiness": "諧音聯想：\n拆解 / 諧音：安（un）＋ 害（hap）＋ 屁（pi）＋ 內（ness）。\n\n聯想畫面 1：他心裡覺得很不快樂，覺得這一切都是安害的，心裡苦惱不已。\n\n聯想畫面 2：儘管擁有財富，他臉上卻總是掛著憂愁，顯得非常不幸福。\n\n高效擴充：un-（不）+ happy（快樂）+ -ness（名詞字尾）。\nKK 音標：[ʌnˋhæpinəs] -> 第二音節重音，注意 happy 變形為 happi。\n\n常見同義字：\n\nsadness（悲傷，通用）\n\nmisery（苦難，程度較深）。",
  "unhappy": "諧音聯想：\n諧音：「安海瑟薇不嗨」\n\n聯想畫面 1：知名女星安海瑟薇今天拍戲遇到雨天，整個人一點都不嗨，顯得很不快樂。\n\n聯想畫面 2：收到不滿意的成績單時，臉上的笑容瞬間消失，心情變得非常不開心。\n\n高效擴充：否定字首 un- 加上 happy (快樂的)，組合成反義詞不快樂的。\nKK 音標：[ənˋhæpi] -> 主重音落在第二音節 hæ 上，開頭 un 念輕短音。\n\n常見同義字：\nsad（傷心的，最基礎用語）\nmiserable（悲慘痛苦的）\ndiscontented（不滿意的，悶悶不樂的）",
  "unhitch": "諧音聯想：\n拆解：un（解開）+ hitch（掛鉤）\n\n聯想畫面 1：農夫熟練地解開馬車的套具，讓馬兒可以休息一下。\n\n聯想畫面 2：他解開了繩子，讓船隻順著水流漂走，徹底放鬆了束縛。\n\n高效擴充：hitch 是掛鉤或套住，unhitch 就是把掛鉤解開。\nKK 音標：[ʌnˋhɪtʃ] -> 重音在第二音節，發音要乾脆。\n\n常見同義字：\n\nunhook（解開鉤子，最常用的替代詞）\n\ndetach（分離，指將物體分開）\n\nrelease（釋放，指鬆開束縛）",
  "unholy": "諧音聯想：\n拆解 / 諧音：un（不）+ holy（神聖）\n\n聯想畫面 1：在神聖的教堂裡做出褻瀆的行為，這簡直是 unholy，令人感到極度罪惡。\n\n聯想畫面 2：這場會議簡直是 unholy 的災難，進度落後又充滿爭吵，極其糟糕。\n\n高效擴充：holy 是神聖，加上否定字首 un，直接轉為負面含義。\nKK 音標：[ʌnˋhoʊli] -> 重音在第二音節，注意 hoʊ 的長母音發音。\n\n常見同義字：\nwicked（邪惡的，強調道德敗壞）\nprofane（褻瀆的，強調對神不敬）\nterrible（糟糕的，用於加強語氣）",
  "unidentified": "諧音聯想：\n拆解 / 諧音：un（不）+ identify（識別）+ ed\n\n聯想畫面 1：雷達上出現一個身分不明的飛行物，讓空軍基地進入警戒狀態。\n\n聯想畫面 2：警方在現場發現一個來源不明的包裹，立刻封鎖了街道。\n\n高效擴充：identify 是識別，加上 un 和 ed 變成形容詞，表示沒被認出來。\nKK 音標：[͵ʌnaɪˋdɛntə͵faɪd] -> 重音在第三音節，唸起來要像在報告一樣正式。\n\n常見同義字：\n\nunknown（未知的，最簡單的說法）\n\nanonymous（匿名的，強調隱藏身分）\n\nunnamed（未具名的，強調名字未公開）",
  "uniform": "諧音聯想：\n諧音：「由你煩」\n\n聯想畫面 1：學校規定每天都要穿制服，學生覺得每天想穿什麼由你煩變得很簡單。\n\n聯想畫面 2：全體員工穿著整齊劃一的制服，展現出品牌一致的專業形象。\n\n高效擴充：uni 代表單一、統一，form 代表形狀，組合成形式統一的制服。\nKK 音標：[ˋjunə͵fɔrm] -> 主重音在最前面的 ju，fɔrm 尾音要往下掉。\n\n常見同義字：\nconsistent（一致的、始終如一的）\nconstant（恆常的、不變的）\nattire（服裝、盛裝）",
  "unify": "諧音聯想：\n拆解 / 諧音：uni（單一、統一）+ fy（動詞字尾）\n\n諧音：「優尼發依」\n\n聯想畫面 1：秦始皇統一六國，將文字與度量衡使之完全一致。\n\n聯想畫面 2：跨國企業透過新政策，將各部門的目標進行聯合與協調。\n\n高效擴充：字根 uni 代表 one（一個），如 unicorn 獨角獸。\nKK 音標：[ˋjunə͵faɪ] -> 主重音在第一個音節 u，發長 u 音。\n\n常見同義字：\n\nunite（聯合、團結，強調結合為一體）\n\nintegrate（整合、使融入，多用於系統或多元文化）\n\ncombine（結合，實體或抽象的搭配皆可）",
  "unimaginable": "諧音聯想：\n拆解 / 諧音：un（不）+ imagine（想像）+ able（能）\n\n聯想畫面 1：宇宙的浩瀚是人類難以想像的，我們只是滄海一粟。\n\n聯想畫面 2：這場災難造成的破壞程度是不可思議的，簡直像電影情節。\n\n高效擴充：imagine 去 e 加 able，變成形容詞，加上 un 就是不能想像。\nKK 音標：[͵ʌnɪˋmædʒɪnəbəl] -> 重音在第三音節，注意 mæ 的發音要開口大。\n\n常見同義字：\n\ninconceivable（不可思議的，強調邏輯上無法理解）\n\nunthinkable（難以想像的，強調程度極端）\n\nincredible（難以置信的，常用於驚嘆）",
  "unimaginativeness": "諧音聯想：\n拆解：un（不）+ imaginative（有想像力的）+ ness（名詞字尾）\n\n聯想畫面 1：這部電影的劇情毫無新意，充分展現了編劇的缺乏想像力。\n\n聯想畫面 2：他總是重複同樣的工作方式，這種無創意的做法讓團隊感到乏味。\n\n高效擴充：imaginative 是有想像力的，加上 un 變成否定，再加 ness 變成名詞。\nKK 音標：無提供 -> 重音在倒數第四音節，發音節奏較長。\n\n常見同義字：\n\nunoriginality（無原創性，指缺乏新意）\n\ndullness（沉悶，指缺乏趣味或創意）\n\nbanality（平庸，指陳腔濫調）",
  "unimportant": "諧音聯想：\n拆解：un（不）+ important（重要的）\n\n聯想畫面 1：這張紙條上的內容瑣碎又無關緊要，直接丟進垃圾桶吧。\n\n聯想畫面 2：在大型會議中，他總是討論一些不重要的細節，浪費大家時間。\n\n高效擴充：important 是重要的，加上否定字首 un- 就是不重要。\nKK 音標：[͵ʌnɪmˋpɔrt(ə)nt] -> 重音在第三音節，唸起來要有一種輕視的語氣。\n\n常見同義字：\ntrivial（瑣碎的）\ninsignificant（無關緊要的）\nminor（次要的）",
  "uninhabited": "諧音聯想：\n拆解：un（不）+ inhabit（居住）+ ed（形容詞）\n\n聯想畫面 1：這座荒島上沒有任何人類居住，只有海鷗在飛，杳無人跡。\n\n聯想畫面 2：探險隊發現了一片無人居住的森林，裡面充滿了原始的氣息。\n\n高效擴充：inhabit 是居住，加上 un 變成否定，非常直觀。\nKK 音標：[͵ʌnɪnˋhæbɪtɪd] -> 重音在第三個音節 ha，唸起來要有層次感。\n常見同義字：\nUnpopulated（人口稀少或無人居住的，較客觀）\nUnoccupied（未被佔用的，可用於空間或房屋）\nBarren（荒蕪的，強調土地貧瘠）",
  "unintelligent": "諧音聯想：\n諧音：「安內聽理智的」\n\n聯想畫面 1：做出這麼荒唐的決定還自以為很有理智，其實非常愚蠢不聰明。\n\n聯想畫面 2：考試時寫出完全不合邏輯的答案，被老師評為缺乏智慧與聰明才智。\n\n高效擴充：un- (不) 加上 intelligent (聰明的)，字面即為不聰明的、愚蠢的。\nKK 音標：[͵ʌnɪnˋtelɪdʒənt] -> 主重音在第三音節 tel，前後音節輕讀。\n\n常見同義字：\nstupid（愚蠢的，最常見）\nsilly（傻氣的，輕微的愚蠢）\nfoolish（愚笨的，不明智的）",
  "uninteresting": "諧音聯想：\n拆解 / 諧音：『un（不） + interesting（有趣的）』\n\n諧音：「un 不 + interesting 有趣」\n\n聯想畫面 1：這本教科書滿篇都是密密麻麻的數字，實在是非常無趣乏味。\n\n聯想畫面 2：聽著沉悶的冗長報告，大家都感到昏昏欲睡、毫無樂趣。\n\n高效擴充：由否定字首 un- 加上形容詞 interesting 形成反義字。\nKK 音標：[ʌnˋɪntrəstɪŋ] -> 主重音在第二音節的 [ɪn]，注意中間弱化省略。\n\n常見同義字：\nboring（直接的乏味、令人生厭）\ndull（枯燥的、陰暗或遲鈍的）\ntiresome（令人疲勞且厭煩的）",
  "uninvolved": "諧音聯想：\n諧音：「安因挖夫」聯想：老公「安」心「因」為他把土「挖」給「夫」家去弄，自己完全「不參與的」。\n\n聯想畫面 1：開會時大家吵得不可開交，他卻戴著耳機喝咖啡，一副置身事外、完全 uninvolved 的樣子。\n\n聯想畫面 2：面對朋友的家務事，他保持理性冷淡，選擇做個 uninvolved 的旁觀者以免惹禍上身。\n\n高效擴充：字首 un- 表示否定，字根 involve 代表捲入或參與，組合起來就是未被捲入、不參與的。\nKK 音標：[͵ʌnɪnˋvɑlvd] -> 主重音在 vɑl 音節，唸快時注意 ul 與 v 的連音，t 尾音輕輕帶過。\n\n常見同義字：\ndetached（冷漠的，情感上疏離的）\nunconnected（無關聯的，未參與的）\nindifferent（漠不關心的，通常置於句中或作表語）",
  "union": "諧音聯想：\n諧音：「優妮昂」工會為了爭取福利，集結所有員工大喊口號展現強大聯盟力量。\n\n聯想畫面 1：工會成員手勾手成立強大聯盟，共同抗議公司的不合理制度。\n\n聯想畫面 2：美國各州組成一個聯邦國家，大家團結在同一個旗幟下。\n\n高效擴充：字根 uni- 代表「單一、一個」，眾人合而為一即為聯盟。\nKK 音標：[ˋjunjən] -> 注意 [ju] 的長音開頭，j 唸作輕柔的子音聲響。\n\n常見同義字：\n\nalliance（同盟，國家或組織間的結盟）\n\nassociation（協會，基於共同利益的組織）\n\nfederation（聯邦，多個州或團體組成的整體）",
  "unique": "諧音聯想：\n諧音：由你客。諧音：「由你客」來決定這個造型，因為它是獨一無二的。\n\n聯想畫面 1：走進一間手作工坊，店長笑著說這個手工包包款式獨一無二、絕對不撞包。\n\n聯想畫面 2：在茫茫人海中，你找到了那個風格獨特、才華洋溢的靈魂伴侶。\n\n高效擴充：字首 uni 代表單一，結合 que 形成獨特的意思，常指獨步全球。\nKK 音標：[juˋnik] -> 主重音在後方的 nik，念起來要俐落有力，ju 則拉長圓唇。\n\n常見同義字：\n\nmatchless（無與倫比的，文學感較重）\n\ndistinctive（有特色的，強調辨識度）\n\nsingular（單一的、非凡的，多用於正式書寫）",
  "uniquely": "諧音聯想：\n諧音：由你客理\n\n聯想畫面 1：這家餐廳的服務是由你客理（由你客人自己打理），這種獨特地經營方式很受歡迎。\n\n聯想畫面 2：她獨特地穿著這件古董旗袍，在人群中顯得與眾不同。\n\n高效擴充：unique（獨特的）+ ly（副詞字尾）。\nKK 音標：[juˋnikli] -> 重音在第二音節，注意 ju 的發音要圓潤。\n\n常見同義字：\n\ndistinctively（顯著地，強調特徵明顯）\n\nspecially（特別地，強調專門）\n\nexceptionally（例外地，強調程度高）",
  "uniqueness": "字根幽默拆解法：unique（世界僅此一家）＋ ness（與眾不同特質）\n\n構造聯想：uniqueness 就是無法被工廠機器大量複製、完全「世界僅此一家」的那股「與眾不同特質」。\n\n記憶畫面：陶藝老師傅親手拉坯上釉的茶碗每個曲線都是「世界僅此一家」，捧在手裡就能感受那份迷人的「與眾不同特質」，充滿藝術品的獨特性 (uniqueness)！",
  "unit": "幽默諧音法：「有你特」\n\n發音聯想：unit [ˋjunət] 唸起來像這個小隊「有你特」別完整。\n\n記憶畫面：我們這個學習小組與單元單位 (unit)，因為「有你特」別加入而變得更加完整強大！",
  "unite": "諧音聯想：\n諧音：「優耐特」\n\n聯想畫面 1：各個優良耐打的武林門派終於放下成見，團結聯合起來對抗外敵。\n\n聯想畫面 2：團隊合作時把所有人的力量緊密結合，才能發揮最強大的戰鬥力。\n\n高效擴充：字首 uni 代表單一、一個，結合起來就是使之成為一個整體。\nKK 音標：[ˋju͵naɪt] -> 主重音在第二音節 nite，第一音節 yu 發輕音。\n\n常見同義字：\n\njoin（加入、結合）\n\ncombine（結合、聯合）\n\nconnect（連接、聯繫）",
  "unity": "諧音聯想：\n諧音：「優你踢」球隊展現出極佳的整體默契，全隊上下團結一致把球踢進球門。\n\n聯想畫面 1：拔河比賽中全隊一條心，展現出完美的團結與一貫性。\n\n聯想畫面 2：交響樂團各個樂器完美融合，呈現出和諧悅耳的整體音樂篇章。\n\n高效擴充：字根 uni- 意指一個，名詞字尾 -ty 讓概念具象化為團結。\nKK 音標：[ˋjunəti] -> 介於中間的 [ə] 要輕聲快速帶過。\n\n常見同義字：\n\nharmony（和諧，強調融洽相處）\n\nsolidarity（團結一致，通常指政治或勞動階級）\n\ncohesion（凝聚力，物理或組織上的緊密結合）",
  "universal": "字根幽默拆解法：uni（全部合一國）＋ vers（旋轉繞整圈）＋ al（全套通用法則）\n\n構造聯想：universal 就是把地球「全部合一國」、不管「旋轉繞整圈」飛到哪一洲都完全行得通的「全套通用法則」。\n\n記憶畫面：真誠友善的微笑能將各國語言隔閡「全部合一國」，帶著它「旋轉繞整圈」環遊世界都適用簡直是「全套通用法則」，成了人類共通普遍的 (universal) 語言！",
  "universe": "諧音聯想：\n諧音：「優你佛斯」這套宇宙無敵的太空衣，讓你能夠自由探索浩瀚的宇宙天地。\n\n聯想畫面 1：太空人站在月球上回望地球，讚嘆整個宇宙的浩瀚與神秘。\n\n聯想畫面 2：天文學家透過望遠鏡觀察滿天星斗，研究宇宙萬物的運行法則。\n\n高效擴充：uni-（一個）加上 verse（轉動），意指萬物旋轉歸於一體的世界。\nKK 音標：[ˋjunə͵vɝs] -> 主重音在第一音節 [ˋjun]，vɝs 要捲舌。\n\n常見同義字：\n\ncosmos（宇宙，強調秩序與調和的宇宙觀）\n\nspace（太空，指地球大氣層以外的空間）\n\ncreation（造物、天地萬物，較文學色彩的說法）",
  "university": "諧音聯想：\n諧音：有你佛系提。諧音：「有你佛系提」出建議，這座綜合性大學才得以順利成立。\n\n聯想畫面 1：高中畢業生穿著制服，興奮地踏入擁有廣大校園的大學殿堂。\n\n聯想畫面 2：圖書館裡坐滿了正在準備期末考的大學生，氣氛十分濃厚。\n\n高效擴充：由 universal 變體而來，專指容納各種學科的高等學府。\nKK 音標：[͵junəˋvɝsəti] -> 主重音在 vɝ，後面 səti 唸得輕快短促。\n\n常見同義字：\n\ncollege（學院，通常規模較小或為大學附屬學院）\n\ninstitute（學會、學院，多指理工或專科）\n\nhigher education（高等教育，泛指大學以上學程）",
  "unjust": "諧音聯想：\n拆解：un（不）+ just（公平的）。\n\n聯想畫面 1：法官判決 unjust，讓無辜的人受罰。\n\n聯想畫面 2：這場比賽裁判偏袒，對另一隊來說太 unjust 了。\n\n高效擴充：just 當形容詞時意為公平的，加 un 變反義。\nKK 音標：[͵ʌnˋdʒʌst] -> 重音在第二音節，注意 u 的短音。\n\n常見同義字：\n\nunfair（不公平的）\n\nbiased（有偏見的）\n\ninequitable（不公正的）。",
  "unknowingly": "拆解：un（不）+ knowing（知道）+ ly。\n\n聯想畫面 1：他不知不覺中走進了陷阱，完全沒發現自己被跟蹤了。\n\n聯想畫面 2：我無意中說出了秘密，當時真的完全不知情。\n\n高效擴充：knowing 是 know 的現在分詞，加上否定字首。\nKK 音標：[ʌnˋnoʊɪŋli] -> 重音在第二音節，注意 know 的長母音。\n\n常見同義字：\n\nunconsciously（無意識地）\n\nunintentionally（無意地）\n\ninadvertently（不經意地）。",
  "unknown": "諧音聯想：\n拆解：un 不 + known 已知的。\n\n聯想畫面 1：這是一個 unknown 的領域，沒有人探索過。\n\n聯想畫面 2：他是一個 unknown 的歌手，還不出名。\n\n高效擴充：know 的過去分詞 known 加上否定字首 un。\nKK 音標：[͵ʌnˋnoʊn] -> 重音在第二個音節，注意 n 的發音。\n\n常見同義字：\n\nunfamiliar（不熟悉的）\n\nanonymous（匿名的）。",
  "unlawful": "諧音聯想：\n拆解 / 諧音：un（否定字首）加上 lawful（合法的）\n\n聯想畫面 1：警察當場逮捕了這群從事非法的走私份子。\n\n聯想畫面 2：在古老的法律條文中，私生子曾被稱為非婚生的。\n\n高效擴充：law 是法律，lawful 是合法，加上 un 變成反義字。\nKK 音標：[ʌnˋlɔfl] -> 重音在第二音節 law，ɔ 唸長音。\n\n常見同義字：\n\nillegal（違法的，最通用的日常用語）\n\nillegitimate（非法的、私生的，較正式）\n\ncriminal（犯罪的，指觸犯刑法的行為）",
  "unless": "字根幽默拆解法：un（如果沒有達成這個條件）＋ less（少於標準就不算數）\n\n構造聯想：unless 就是設立門檻規定「如果沒有達成這個條件」或「少於標準就不算數」，換句話說就是「除非如何不然就不行」。\n\n記憶畫面：密室逃脫大門上寫著「如果沒有達成這個條件」轉開三把銅鑰匙否則打不開，甚至時間「少於標準就不算數」也要加倍思考，馬上掌握除非如果不 (unless) 的邏輯！",
  "unlikely": "諧音聯想：\n拆解：un（不）＋likely（可能的）。\n\n聯想畫面 1：明天會下雪是不大可能發生的事。\n\n聯想畫面 2：這兩個人性格完全不般配，很難想像他們會在一起。\n\n高效擴充：likely 是形容詞，unlikely 為其否定。\nKK 音標：[ʌnˋlaɪkli] -> 重音在第二音節，laɪ 發長音，結尾 kli 輕快。",
  "unlimited": "諧音聯想：\n諧音：安理米特\n\n聯想畫面 1：這張吃到飽的餐券是無限制的，你想吃多少就吃多少。\n\n聯想畫面 2：網路方案提供無限量的數據流量，再也不用擔心追劇會斷線。\n\n高效擴充：un（不）+ limit（限制）+ ed，沒有限制的。\nKK 音標：[ənˋlɪmətɪd] -> 重音在第二音節，注意 lɪm 的短母音。\n\n常見同義字：\n\nboundless（無邊無際的，強調範圍）\n\ninfinite（無限的，強調數學或哲學概念）\n\nunrestricted（不受限制的，強調沒有規則束縛）",
  "unlock": "諧音聯想：\n拆解 / 諧音：un（打開）+ lock（鎖）\n\n諧音：「安拉克」\n\n聯想畫面 1：房東拿著鑰匙插進孔內，輕鬆轉動開鎖。\n\n聯想畫面 2：密碼輸入正確後，手機螢幕瞬間解鎖並釋放畫面。\n\n高效擴充：lock 是鎖，un 是解除，組合成開鎖。\nKK 音標：[ənˋlɑk] -> 主重音在第二個音節 lock，發短 o 音。\n\n常見同義字：\n\nopen（打開，泛指門窗或箱子）\n\nrelease（釋放、解脫，常指釋放潛能或禁錮）\n\nfree（解放、使自由）",
  "unlucky": "諧音聯想：\n拆解：un（不）+ lucky（幸運的）\n\n聯想畫面 1：他今天出門踩到狗屎，真是 unlucky，倒霉透頂的一天。\n\n聯想畫面 2：這間房子據說會招致厄運，大家都覺得住進去很不吉利。\n\n高效擴充：lucky 是幸運，un- 是常見的否定字首。\nKK 音標：[ʌnˋlʌki] -> 第二音節 lʌk 重音，發音像拉，結尾 ki 輕短。\n\n常見同義字：\nunfortunate（指不幸的，較正式）\nhapless（指運氣不佳的，較文學）\nill-fated（指命運多舛的）",
  "unmarried": "拆解：un（不）+ married（已婚）。\n\n聯想畫面 1：填寫表格時，在婚姻狀況欄位勾選未婚，代表目前單身。\n\n聯想畫面 2：現代社會中，越來越多人選擇維持未婚狀態，享受自由生活。\n\n高效擴充：與 single 同義，但 unmarried 更強調婚姻狀態的法律定義。\nKK 音標：[͵ʌnˋmærid] -> 重音在第二音節 ma，發音時注意 r 的捲舌音。",
  "unnatural": "諧音聯想：\n拆解 / 諧音：un（不）＋natural（自然的）。\n\n聯想畫面 1：機器人笑起來很不自然，動作僵硬，看起來非常 unnatural。\n\n聯想畫面 2：他對待親人的態度冷漠，簡直是不近人情的 unnatural 行為。\n\n高效擴充：字首 un 表示否定。\nKK 音標：[ʌnˋnætʃrəl] -> 第二音節重音，注意 tʃr 的連音。\n\n常見同義字：\n\nartificial（人造的）\n\nabnormal（反常的）。",
  "unnecessarily": "諧音聯想：\n拆解 / 諧音：安內塞沙理。\n\n聯想畫面 1：他把房間堆滿雜物，安內塞沙理，完全是不必要地浪費空間。\n\n聯想畫面 2：這份報告寫得太長，不必要地增加了閱讀負擔。\n\n高效擴充：un-否定 + necessary必要的 + -ly副詞。\nKK 音標：[͵ʌn͵nesəˋserəli] -> 主重音在第四音節 ser，發音節奏較長。\n\n常見同義字：\n\nneedlessly不必要地，excessively過度地，superfluously多餘地。",
  "unnecessary": "諧音聯想：\n諧音：安內塞塞\n\n聯想畫面 1：行李箱裡塞滿了安內塞塞（裡面塞太多）的雜物，很多都是不必要的。\n\n聯想畫面 2：這場會議討論的內容多半是無用的廢話，顯得非常不必要。\n\n高效擴充：un（不）+ necessary（必要的）。\nKK 音標：[ənˋnɛsə͵sɛri] -> 重音在第二音節，注意連續的 s 音發音要清晰。\n\n常見同義字：\n\nneedless（不需要的，強調多餘）\n\nredundant（多餘的，強調重複）\n\nsuperfluous（過剩的，較正式）",
  "unnerved": "諧音聯想：\n拆解 / 諧音：un（不）+ nerve（神經/勇氣）+ ed。\n\n聯想畫面 1：突如其來的意外讓他感到心神不寧，整個人都氣餒了。\n\n聯想畫面 2：對手強大的氣場讓他失去勇氣，表現大失水準。\n\n高效擴充：nerve 原意為神經，引申為勇氣。\nKK 音標：[ʌnˋnɝvd] -> 第二音節重音，注意結尾 d 的輕音。\n\n常見同義字：\n\nDisheartened（氣餒的）\n\nUnsettled（不安的）。",
  "unopened": "諧音聯想：\n拆解：un（不）+ opened（打開的）\n\n聯想畫面 1：這份禮物包裝精美，至今仍未開啟，充滿了神秘感。\n\n聯想畫面 2：超市架上的罐頭都是未開封的，確保食品的安全與新鮮。\n\n高效擴充：un 是否定字首，加上動詞過去分詞作為形容詞使用。\nKK 音標：[ʌnˋoʊpənd] -> 重音在第二個音節，注意 un 的否定語氣。\n\n常見同義字：\nsealed（密封的，強調未被損壞）\nintact（完整的，指未被動過）\nnew（新的，暗示未被使用過）",
  "unpack": "諧音聯想：\n拆解 / 諧音：un（拿出、打開）+ pack（包裹、行李）\n\n諧音：「安培克」\n\n聯想畫面 1：旅客剛抵達飯店房間，立刻打開行李箱拿出戰利品。\n\n聯想畫面 2：偵探開始分析與剖析這起複雜的懸疑案件線索。\n\n高效擴充：pack 是打包，unpack 是反向動作「拆包裹」。\nKK 音標：[ənˋpæk] -> 主重音在第二個音節 pack，發短 a 音。\n\n常見同義字：\n\nempty（倒出、使空，多用於倒出容器內物）\n\nanalyze（分析、剖析，用於資料或案情）\n\ndisclose（揭露、透露）",
  "unpleasant": "諧音聯想：\n拆解：un（不）+ pleasant（令人愉快的）\n\n聯想畫面 1：這場會議氣氛非常不愉快，大家都在爭吵。\n\n聯想畫面 2：他對服務生的態度很不客氣，讓人感到非常不舒服。\n\n高效擴充：pleasant 是愉快的，加上否定字首 un- 即為不愉快。\nKK 音標：[ʌnˋplez(ə)nt] -> 第二音節 plez 重音，發音像普雷，後綴輕讀。\n\n常見同義字：\ndisagreeable（指令人不快的、難相處的）\nunfriendly（指不友善的）\nannoying（指惱人的）",
  "unprecedented": "諧音聯想：\n拆解：un（不）+ precedent（先例）+ ed\n\n聯想畫面 1：這場大雨造成了 unprecedented 的災情，以前從來沒見過這麼嚴重的淹水。\n\n聯想畫面 2：這項科技突破是 unprecedented 的，人類歷史上從未有過這樣的成就。\n\n高效擴充：precedent 是先例，加上否定前綴 un-，就是沒有先例的。\nKK 音標：[ʌnˋpresɪdentɪd] -> 重音在第二音節 pres，發音時要清晰地唸出每個音節。\n\n常見同義字：\n\nunparalleled（無與倫比的，強調沒有對手）\n\nnovel（新穎的，強調創新）\n\noriginal（原創的，強調獨特性）",
  "unprepared": "諧音聯想：\n諧音：安（un）+ 普（pre）+ 派（pared）。\n\n聯想畫面 1：考試前完全沒準備，老師突然點名，我只好即席亂講，真是太沒準備了。\n\n聯想畫面 2：突如其來的暴雨讓沒帶傘的行人都顯得毫無準備，狼狽地躲在騎樓下。\n\n高效擴充：un- 表示否定，prepare 是準備，加上 -ed 變成形容詞。\nKK 音標：[͵ʌnprɪˋperd] -> 重音在第三音節，唸起來要有那種措手不及的感覺。\n\n常見同義字：\n\nunready（未準備好的）\n\ncaught off guard（措手不及的）\n\nspontaneous（即興的，指沒準備的）。",
  "unreal": "諧音聯想：\n諧音：安瑞兒。\n\n聯想畫面 1：安瑞兒這個人太不真實了，簡直像從漫畫裡走出來的虛構人物。\n\n聯想畫面 2：這場表演實在太絕妙了，簡直讓人覺得很不真實。\n\n高效擴充：un（不）加 real（真實）。\nKK 音標：[͵ʌnˋriəl] -> 重音在第二音節，ri 讀長音，結尾的 l 舌尖輕抵上顎。",
  "unremarkable": "諧音聯想：\n拆解：un（不）+ remarkable（值得注意的）。\n\n聯想畫面 1：這棟建築外觀非常 unremarkable，走在路上很容易被忽略。\n\n聯想畫面 2：醫生檢查後說身體狀況 unremarkable，表示一切都很正常，不用擔心。\n\n高效擴充：remarkable 是卓越的，加上 un- 變成平凡的。\nKK 音標：[͵ʌnrɪˋmɑrkəbl] -> 第三音節重音，注意 r 的捲舌音。\n\n常見同義字：\nordinary（普通的，指一般水準）\ncommonplace（平凡的，指隨處可見的）\nmediocre（平庸的，指品質平平的）",
  "unrepentant": "諧音聯想：\n拆解：un（不）＋repent（後悔）＋ant。\n\n聯想畫面 1：犯人站在法庭上依然不後悔，態度頑固不化。\n\n聯想畫面 2：他做了錯事卻執迷不悟，完全沒有羞愧感。\n\n高效擴充：repent 意為後悔，加上 ant 變成形容詞。\nKK 音標：[͵ʌnrɪˋpentənt] -> 重音在第三音節，pent 發音有力。",
  "unresolved": "諧音聯想：\n諧音：安瑞走了（un-re-solved）\n\n聯想畫面 1：安瑞這傢伙突然走掉了，留下桌上那一堆未解決的爛攤子，讓大家懸而未決。\n\n聯想畫面 2：音樂會上和聲突然中斷，聽起來像沒解決的懸疑片結尾，讓人心裡七上八下。\n\n高效擴充：字首 un- 表示否定，字根 resolve 是解決，合起來就是還沒解決的。\nKK 音標：[͵ʌnrɪˋzɑlvd] -> 重音在第二音節，唸起來要有種事情還卡住的頓挫感。\n\n常見同義字：\nundecided（指人猶豫不決）\nunsettled（指情況尚未定案）\nopen（指問題仍開放討論）",
  "unruffled": "諧音聯想：\n拆解：un（不）+ ruffled（弄亂的、起皺的）\n\n聯想畫面 1：面對突發的危機，他依然保持鎮定，情緒完全沒有被弄亂。\n\n聯想畫面 2：清晨的湖面平靜無波，像鏡子一樣，完全沒有被風吹動的痕跡。\n\n高效擴充：ruffle 原意是弄皺、使起皺，加上 un- 表示沒有被弄亂。\nKK 音標：[ʌnˋrʌfld] -> 第二音節 rʌf 重音，發音像拉夫，結尾 ld 輕讀。\n\n常見同義字：\ncalm（指冷靜的、平靜的）\ncomposed（指鎮定的、沉著的）\nserene（指安詳的、寧靜的）",
  "unsafe": "拆解：Un（不）+ Safe（安全）。\n\n聯想畫面 1：這座橋看起來搖搖欲墜，走上去絕對是不安全的。\n\n聯想畫面 2：在深夜的巷弄裡，獨自一人會讓人感到不安穩。\n\n高效擴充：Un 是常見否定字首，加在形容詞前表示相反。\nKK 音標：[ʌnˋseɪf] -> 重音在第二音節，safe 的長母音要發足。\n\n常見同義字：\n\ndangerous（危險的，程度較強）\n\nrisky（有風險的）。",
  "unsanitary": "諧音聯想：\n諧音：安山尼塔瑞\n\n聯想畫面 1：這間餐廳的廚房髒亂不堪，非常不衛生，讓人看了就想吐。\n\n聯想畫面 2：在路邊攤吃東西要小心，有些環境有礙健康，容易引發腸胃炎。\n\n高效擴充：un（不）+ sanitary（衛生的）。\nKK 音標：[ənˋsænə͵tɛri] -> 重音在第二音節，注意 sæn 的發音要飽滿。\n\n常見同義字：\n\nunhygienic（不衛生的，最直接的對應詞）\n\ndirty（髒的，最基礎）\n\nunclean（不乾淨的，強調狀態）",
  "unsatisfactory": "拆解：un（不）+ satisfactory（令人滿意的）\n\n諧音：「安妮撒死費克特裡」\n\n聯想畫面 1：安妮交出的報告因為內容太爛，被主管批為 unsatisfactory。\n\n聯想畫面 2：這次期末考的成績很不理想，讓家長感到 unsatisfactory。\n\n高效擴充：un- 否定字首加在 satisfactory 形成相反詞。\nKK 音標：[͵ʌnsətɪˋsfæktɚi] -> 主重音在 fa 所在音節，發短音 /æ/。\n\n常見同義字：\nunacceptable（無法接受的、不合格的）\ninadequate（不充分的、不夠好的）\npoor（表現差勁的、不佳的）",
  "unscrupulousness": "諧音聯想：\n拆解 / 諧音：安（un）+ 刷（scrup）+ 普（u）+ 魯（lous）+ 內（ness）。\n\n聯想畫面 1：他為了成功不擇手段，展現出極度的狂妄。\n\n聯想畫面 2：商場上的不擇手段行為，往往會讓人感到憤怒。\n\n高效擴充：un-（不）+ scrupulous（有顧忌的），意指毫無顧忌。\nKK 音標：[ʌnˋskrupjələsnəs] -> 重音在第二音節，發音要長且帶有批判感。\n\n常見同義字：\n\nruthlessness（殘忍）\n\nimmorality（不道德）\n\ndishonesty（不誠實）。",
  "unsettled": "諧音聯想：\n諧音：安設特。\n\n聯想畫面 1：因為還有很多 unsettled 的帳單，他感到非常心神不寧。\n\n聯想畫面 2：這片土地目前還是 unsettled，沒有人居住。\n\n高效擴充：un（不）+ settle（定居、解決）+ ed，形容狀態未定。\nKK 音標：[ʌnˋsetld] -> 第二音節 set 重讀，發音像「設」，強調未被安頓好的狀態。",
  "unsolvable": "諧音聯想：\n拆解：un 不 + solvable 可解決的。\n\n聯想畫面 1：這是一個 unsolvable 的謎題，沒有人能解開。\n\n聯想畫面 2：他面對 unsolvable 的困境，感到非常無助。\n\n高效擴充：由 solve 解決加上 able 和 un 組成。\nKK 音標：[ʌnˋsɑlvəbl] -> 重音在第二個音節，唸起來很順口。\n\n常見同義字：\n\ninsoluble（較正式，也可用於化學）\n\nunanswerable（無法回答的）。",
  "unsporting": "拆解：un（不）+ sporting（運動精神的）。\n\n聯想畫面 1：比賽中對手故意絆倒別人，這種無體育道德的行為被全場觀眾噓爆。\n\n聯想畫面 2：他不遵守規則贏得比賽，被認為是不光明正大的小人。\n\n高效擴充：sporting 指具有運動家精神，加上 un 表示否定。\nKK 音標：[͵ʌnˋspɔrtɪŋ] -> 重音在第二音節 sport，注意 r 的捲舌音。\n\n常見同義字：\n\nunfair（不公平的）\n\ndishonorable（不光彩的）\n\nunsportsmanlike（無運動家精神的）。",
  "unstated": "諧音聯想：\n拆解 / 諧音：un（不）+ stated（聲明的）。\n\n聯想畫面 1：雖然合約上未明確說明，但雙方都心照不宣。\n\n聯想畫面 2：他那未說出的擔憂，全寫在緊鎖的眉頭上。\n\n高效擴充：state 為聲明，加 un 表示否定。\nKK 音標：[ʌnˋsteɪtɪd] -> 第二音節重音，注意結尾 ed 的發音。\n\n常見同義字：\n\nImplicit（含蓄的）\n\nUnspoken（未說出的）。",
  "unsure": "諧音聯想：\n諧音：安修（un-sure）\n\n聯想畫面 1：安修站在路口，看著地圖一臉不確定，完全沒把握該往左還是往右走。\n\n聯想畫面 2：面試時被問到專業問題，他支支吾吾顯得缺乏信心，看起來就是一副沒準備好的樣子。\n\n高效擴充：由 un- 加 sure 組成，sure 是確定的，加了否定字首就是不確定。\nKK 音標：[͵ʌnˋʃʊr] -> 重音在後，sure 的發音要像是在說確定時的那個長音。\n\n常見同義字：\nuncertain（較正式，指情況不明）\ndoubtful（指心存懷疑）\nhesitant（指猶豫不決）",
  "unsweetened": "諧音聯想：\n拆解 / 諧音：安（un）＋ 甜（sweet）＋ 的（ened）\n\n諧音：安甜的\n\n聯想畫面 1：這杯咖啡沒有加糖，雖然不甜，但安安靜靜地喝著，反而能品嚐出咖啡豆原本的香氣。\n\n聯想畫面 2：健康飲食提倡喝無糖飲料，這瓶果汁是未加糖的，喝起來清爽無負擔。\n\n高效擴充：un（否定）＋ sweet（甜）＋ ened（動詞變形容詞），指沒有被加糖的狀態。\nKK 音標：[͵ʌnˋswitnd] -> 重音在第二個音節，sweet 發長音 i，唸起來要拉長。\n\n常見同義字：\n\nplain（純的，指沒有添加物）\n\nbitter（苦的，有時無糖飲料會帶苦味）\n\nunsugared（未加糖的，較直接的說法）",
  "unsympathetic": "諧音聯想：\n拆解：un（不）＋sympathetic（同情的）。\n\n聯想畫面 1：他對受災戶無動於衷，表現得非常不表同情。\n\n聯想畫面 2：這部戲裡的反派角色非常令人生厭，觀眾都不喜歡。\n\n高效擴充：sympathy（同情心）的形容詞變化。\nKK 音標：[͵ʌn͵sɪmpəˋθetɪk] -> 重音在第四音節，注意 th 的咬舌音。",
  "untidy": "諧音聯想：\n諧音：安，太低。\n\n聯想畫面 1：房間裡的書架安放得太低，導致東西亂丟，看起來非常 untidy。\n\n聯想畫面 2：他出門前總是不整理儀容，頭髮亂翹、襯衫沒紮，整個人看起來很 untidy。\n\n高效擴充：un 是否定字首，tidy 是整潔的，合起來就是不整潔。\nKK 音標：[ʌnˋtaɪdi] -> 重音在第二音節 ti，注意 i 的長音發音。\n\n常見同義字：\n\nmessy（雜亂的，最常用）\n\ndisordered（無序的，較正式）\n\nsloppy（邋遢的，指人）。",
  "until": "幽默諧音法：「俺挑」\n\n發音聯想：until [ənˋtɪl] 唸起來像「俺挑」選到滿意為止。\n\n記憶畫面：他在書店裡認真翻閱，說「俺挑」好書一定要細心挑選直到 (until) 找到最棒的那本為止！",
  "unto": "諧音聯想：\n諧音：安（un）＋吐（to）。\n\n聯想畫面 1：古文說愛人如愛己，愛 unto 你的鄰居。\n\n聯想畫面 2：這座島嶼自成一體，a world unto itself，與世隔絕。\n\n高效擴充：這是 to 的古體或文學用法，常出現在聖經或詩歌中。\nKK 音標：[ˋʌntə͵ˋʌntu] -> 第一音節重音，注意它是介系詞。\n\n常見同義字：\n\nto（到）\n\nuntil（直到）。",
  "untouched": "拆解：un（不）+ touched（觸碰）。\n\n聯想畫面 1：桌上的蛋糕完全沒人動過，看起來就像剛端出來一樣完好無缺。\n\n聯想畫面 2：他聽到悲慘的故事卻面無表情，心靈完全未受影響，顯得非常冷漠。\n\n高效擴充：touch 的過去分詞加上否定前綴 un，表示狀態未被改變。\nKK 音標：[ʌnˋtʌtʃt] -> 重音在第二音節 touch，結尾的 t 輕輕帶過即可。\n\n常見同義字：\n\npristine（原始的，未受污染的）\n\nintact（完整無缺的）\n\nunaffected（未受影響的）。",
  "untoward": "諧音聯想：\n諧音：安（un）＋吐（to）＋窩（ward）的。\n\n聯想畫面 1：原本平靜的聚會，突然有人吐了一窩，真是個 untoward 的意外插曲。\n\n聯想畫面 2：他在會議上說了不合禮數的話，顯得非常 untoward。\n\n高效擴充：un（不）＋toward（向著），指事情發展不順心。\nKK 音標：[ʌnˋtɔrd] -> 第二音節重音，tɔrd 發音像 torn 的變體。\n\n常見同義字：\n\nunexpected（意外的）\n\nimproper（不適當的）。",
  "untrue": "諧音聯想：\n拆解 / 諧音：「un（不）＋ true（真實的）」\n\n聯想畫面 1：這則網路新聞報導完全不是真的，是虛構的謠言。\n\n聯想畫面 2：他對婚姻不忠實，背叛了兩人的誓言。\n\n高效擴充：字首 un 代表相反，true 是真實的，合起來指不真實、不忠實或不合標準。\nKK 音標：[ʌnˋtru] -> 重音在第二音節 ˋtru，發音時注意 u 的長音。\n\n常見同義字：\n\nfalse（假的，不真實的）\n\nunfaithful（不忠實的，背叛的）\n\nfabricated（捏造的，虛構的）",
  "unusual": "諧音聯想：\n諧音：「安居酒屋」聯想：在「安」靜的「居酒屋」裡竟然出現一隻大猩猩，實在是太「不尋常的」畫面了。\n\n聯想畫面 1：今天的天空出現了 unusual 的七彩雲朵，吸引路人紛紛拿起手機拍照。\n\n聯想畫面 2：他今天表現得非常 unusual，不僅沒吃早餐，還提早半小時上班。\n\n高效擴充：字首 un- 表示否定，加上 usual（通常的），組合起來就是不尋常、罕見的。\nKK 音標：[ʌnˋjuʒuəl] -> 主音節在 juʒ 音節，注意 s 發成 z 的濁音，尾音 -ual 唸輕聲。\n\n常見同義字：\nuncommon（罕見的，不普遍的）\nrare（稀有的，珍貴的）\nextraordinary（非凡的，特異的）",
  "unvarnished": "拆解：un（不）+ varnish（塗漆）。\n\n聯想畫面 1：這張桌子沒有塗漆，呈現最原始的木頭紋路。\n\n聯想畫面 2：他說話不加修飾，直接講出真相。\n\n高效擴充：varnish 指清漆，引申為修飾。\nKK 音標：[͵ʌnˋvɑrnɪʃt] -> 重音在第二音節 var。\n\n常見同義字：\n\nplain（樸素的）\n\nfrank（坦率的）\n\ntruthful（真實的）。",
  "unwed": "諧音聯想：\n諧音：安穩的。\n\n聯想畫面 1：現代社會中，許多人覺得未婚 unwed 的狀態反而過得更安穩自在。\n\n聯想畫面 2：法律文件上常看到 unwed mother，指未婚媽媽。\n\n高效擴充：un 是否定字首，wed 是結婚，合起來就是未結婚。\nKK 音標：[͵ʌnˋwed] -> 重音在第二音節，wed 的 e 發短母音。\n\n常見同義字：\n\nsingle（單身）\n\nunmarried（未婚）\n\nbachelor（單身漢）。",
  "unwedded": "拆解：un + wed + ded。\n\n聯想畫面 1：這對情侶愛情長跑多年，依然 unwedded，還沒步入禮堂。\n\n聯想畫面 2：在文學作品中，unwedded 常形容尚未結合的靈魂。\n\n高效擴充：這是 unwed 的形容詞延伸，強調尚未完成結婚儀式的狀態。\nKK 音標：無 -> 重音在第二音節，發音類似 unwed 再加上 ded 的尾音。\n\n常見同義字：\n\nunmarried（未婚）\n\nsingle（單身）\n\nunattached（未有伴侶的）。",
  "unwelcome": "諧音聯想：\n拆解 / 諧音：安，威爾康（unwelcome）\n\n聯想畫面 1：安，威爾康（unwelcome）！這是一個反諷，當一個不受歡迎的人走進來，大家卻假裝熱情地說歡迎，其實心裡都覺得他很討厭。\n\n聯想畫面 2：在派對上，那個不請自來的陌生人，顯然是個不受歡迎的客人。\n\n高效擴充：un- 否定，welcome 歡迎，字面意思就是沒人歡迎。\nKK 音標：[ʌnˋwelkəm] -> 重音在第二音節，wel 的發音要短促，come 的發音要輕。\n\n常見同義字：\n\nunwanted（不被需要的，強調多餘感）\n\nrejected（被拒絕的，強調被排斥）\n\nundesirable（令人不悅的，強調不符合期待）",
  "unwell": "諧音聯想：\n諧音：「安我囉」\n\n聯想畫面 1：身體不舒服時躺在床上對家人說安撫我囉，因為頭暈腦脹生病了。\n\n聯想畫面 2：早上起床覺得喉嚨痛，打電話向公司請假表示今天身體微恙不能上班。\n\n高效擴充：否定字首 un- 加上 well (健康的)，常放在be動詞後面作表語。\nKK 音標：[ʌnˋwel] -> 重音在第二音節 wel，開頭 un 念短音。\n\n常見同義字：\nsick（生病的，美式常用）\nill（生病的，較正式或常作表語）\nunder the weather（身體不適的慣用語）",
  "unwilling": "諧音聯想：\n拆解 / 諧音：安，威靈（unwilling）\n\n聯想畫面 1：安，你威靈（unwilling）嗎？這句話聽起來很怪，其實就是問你是不是不願意配合，表現出勉強的樣子。\n\n聯想畫面 2：小孩子被強迫去補習班時，臉上寫滿了不情願，那種勉強的神情就是 unwilling。\n\n高效擴充：un- 為否定字首，willing 為意願，合起來就是沒有意願。\nKK 音標：[ʌnˋwɪlɪŋ] -> 重音在第二音節，注意 w 的發音嘴型要圓，結尾的 ng 要鼻腔共鳴。\n\n常見同義字：\n\nreluctant（勉強的，心裡有抗拒感）\n\nloath（不願意的，語氣較強烈）\n\nhesitant（猶豫的，不確定是否要做的）",
  "unwind": "諧音聯想：\n諧音：「安完得」\n\n聯想畫面 1：工作終於安完得（unwind）啦，趕緊躺在沙發上好好放鬆一下，解除一整天的疲勞。\n\n聯想畫面 2：下班後到公園散步，把耳機線慢慢解開、展開（unwind），讓心情跟著音樂沈澱下來。\n\n高效擴充：un（不）加上 wind（捲動、上發條），把發條鬆開就是放鬆或解開的意思。\nKK 音標：[͵ʌnˋwaɪnd] -> 主重音在尾音的 wind，唸長母音 ai，像是在嘆氣說「歪了」。\n\n常見同義字：\nrelax（放鬆，最常用的日常詞彙）\nchill（放鬆、鎮定，較為口語輕鬆）\nunwind（放鬆、解除緊繃，常指排解壓力）」",
  "unwonted": "諧音聯想：\n諧音：安萬得。\n\n聯想畫面 1：他 unwonted 地早起，這對他來說很不尋常。\n\n聯想畫面 2：他 unwonted 的熱情讓大家感到驚訝。\n\n高效擴充：wont 是習慣的意思，unwonted 就是不習慣的、不尋常的。\nKK 音標：[ʌnˋwoʊntɪd] -> 重音在第二個音節，注意 o 的發音。\n\n常見同義字：\n\nunusual（不尋常的）\n\nrare（罕見的）。",
  "unworldly": "拆解：un（不）+ worldly（世俗的）。\n\n聯想畫面 1：他不食人間煙火，像個不屬於這世俗的修行者，淡泊名利。\n\n聯想畫面 2：那個天真的孩子眼神清澈，完全不諳世故，給人一種超凡脫俗的感覺。\n\n高效擴充：worldly 是世俗的，加上否定字首 un 就變成脫離世俗的。\nKK 音標：[ʌnˋwɝldli] -> 重音在第二音節 wɝ，發音時舌頭捲起。\n\n常見同義字：\n\nSpiritual（精神上的）\n\nNaive（天真的）\n\nOtherworldly（超凡的）。",
  "up": "幽默諧音法：「阿撲」\n\n發音聯想：up [ʌp] 唸起來就像「阿撲」往上跳。\n\n記憶畫面：貓咪瞄準衣櫃頂端，「阿撲」一聲用力向上 (up) 跳上最高處！",
  "upbeat": "諧音聯想：\n諧音：阿比。\n\n聯想畫面 1：他總是保持樂觀的態度，心情 upbeat。\n\n聯想畫面 2：這首音樂節奏強烈，聽起來非常 upbeat。\n\n高效擴充：up（向上）+ beat（拍子），指情緒高昂。\nKK 音標：[ˋʌpbit] -> 重音在第一音節，發音輕快。",
  "upbringing": "諧音聯想：\n諧音：「阿爸冰」\n\n聯想畫面 1：阿爸買冰給小孩吃，從小到大細心呵護，這就是優良的養育與教養過程。\n\n聯想畫面 2：在嚴格的家庭環境中成長，長輩用規矩養育出懂禮貌的小孩。\n\n高效擴充：up（向上）加上 bring（帶來），把孩子向上帶大就是養育。\nKK 音標：[ˋʌ͵pbrɪŋɪŋ] -> 第一音節重音，念短促的 u，後面的 bring 發鼻音。\n\n常見同義字：\nparenting（父母的教養方式與照顧，強調過程與技巧）\nraising（養育、飼養，範圍較廣可用於人或動植物）\nbreeding（繁育、飼養，多用於動物或特定背景）",
  "upcoming": "諧音聯想：\n諧音：阿婆看明\n\n聯想畫面 1：阿婆看明（看著明天）的行事曆，準備參加即將來臨的社區活動。\n\n聯想畫面 2：這部即將到來的電影預告片，已經在網路上引起了熱烈討論。\n\n高效擴充：up（向上/向前）+ coming（來），向前走過來，就是即將來臨。\nKK 音標：[ˋʌp͵kʌmɪŋ] -> 重音在第一個音節，注意 up 的發音要短促有力。\n\n常見同義字：\n\nforthcoming（即將到來的，較正式）\n\napproaching（接近中的，強調時間或空間）\n\nnear（近的，最簡單）",
  "update": "諧音聯想：\n諧音：「阿ㄆㄧ特」\n\n聯想畫面 1：手機跳出通知提醒使用者立即更新軟體，以獲得最新資訊。\n\n聯想畫面 2：開會時主管要求大家同步最新的專案進度與市場消息。\n\n高效擴充：由 up（向上）加上 date（日期）組成，把日期推進到最新狀態。\nKK 音標：[əpˋdet] -> 主重音在第二音節 date，唸起來像「ㄜˋㄆˋ代特」。\n\n常見同義字：\n\nrenew（換新、更新合約或證件）\n\nupgrade（升級，通常指硬體或版本提升）\n\nrefresh（重新整理網頁或畫面）",
  "upgrade": "諧音聯想：\n諧音：「阿婆隔壁」\n\n聯想畫面 1：阿婆隔壁的手機店推出舊機換新機活動，幫顧客的手機系統全面升級。\n\n聯想畫面 2：電腦跑不動時，花錢把硬體升級，讓工作效率大幅提高。\n\n高效擴充：up（向上）加上 grade（等級），把等級往上提升就是升級。\nKK 音標：[əpˋɡred] -> 第二音節 grade 重音，起伏要明顯。\n\n常見同義字：\nimprove（改善、增進，強調品質變好）\nupdate（更新，通常指軟體或資訊與時俱進）\nenhance（提高、增強，多用於抽象能力或價值）",
  "uphold": "諧音聯想：\n拆解 / 諧音：up（向上）+ hold（拿著、抓著）\n\n諧音：「阿普後德」\n\n聯想畫面 1：抗議民眾高舉布條，全力維護言論自由的價值。\n\n聯想畫面 2：大法官堅定地支援法律的公正性，支撐著社會正義。\n\n高效擴充：up 向上 + hold 抓住，字面意為「向上抓牢、撐住」。\nKK 音標：[əpˋhold] -> 主重音在第二個音節 hold，發雙母音 o。\n\n常見同義字：\n\nsupport（支援、支持，最常用的日常詞）\n\nmaintain（維持、保持，強調持續維護現狀）\n\ndefend（防衛、辯護，強調保護不受侵害）",
  "uplift": "諧音聯想：\n拆解 / 諧音：『up（向上） + lift（舉起）』\n\n諧音：「up 向上 + lift 電梯」\n\n聯想畫面 1：像搭電梯一樣向上提升，把低落的心靈與精神鼓舞起來。\n\n聯想畫面 2：山區地殼發生劇烈隆起，整個地形向上抬高。\n\n高效擴充：由副詞 up 與動詞 lift 組合而成的實用合成字。\nKK 音標：[ˋʌplɪft] -> 主重音在第一音節 [ˋʌp]，後半部短促有力。\n\n常見同義字：\nelevate（提升、舉起）\nraise（舉起、提高）\ninspire（鼓舞、激勵精神）",
  "upload": "諧音聯想：\n拆解 / 諧音：「up（向上）＋ load（載貨）」\n\n諧音：把車上的貨物「up（往上）」搬到雲端貨櫃裡，就是上傳檔案。\n\n聯想畫面 1：攝影師把剛拍好的高畫質婚紗照透過網路順利上傳到雲端硬碟。\n\n聯想畫面 2：網紅剪輯好新影片後點擊發布，等待系統讀取並上傳至影音平台。\n\n高效擴充：與 download（下載）剛好是一對反義詞，down 是往下，up 是往上。\nKK 音標：[ˋʌp͵lod] -> 重音在第一音節 up，load 發長雙母音 oʊ。\n\n常見同義字：\nsend up（向上發送，較少用）\npost（發佈，社交媒體常用的上傳與發文動作）\npublish（出版、發行，較正式的內容公開）",
  "upon": "字根幽默拆解法：up（穩穩往上頭放上去）＋ on（貼合接觸在表面上）\n\n構造聯想：upon 就是比單純擺著更有「穩穩往上頭放上去」然後「貼合接觸在表面上」的書面親切感，代表在…之上或一旦基於此事。\n\n記憶畫面：童話書最愛寫從前有個國王把金冠「穩穩往上頭放上去」而且「貼合接觸在表面上」絲絨墊，同時我們一切計畫也建立在誠信與行動基於在……上 (upon)！",
  "upper": "諧音聯想：\n諧音：「阿爸」\n\n聯想畫面 1：阿爸站在樓梯上面較高的位置呼喚我。\n\n聯想畫面 2：鞋幫鞋面（upper）是鞋子上面的部分。\n\n高效擴充：由 up（向上）衍生而來的比較級概念字。\nKK 音標：[ˋʌpɚ] -> 重音在第一音節，尾音捲舌。\n\n常見同義字：\n\nhigher（更高位置的，比較級用法）\n\ntop（頂部的、最上面的）\n\nsuperior（較優越的、上級的，較正式）",
  "upright": "諧音聯想：\n諧音：「阿普萊特」\n\n聯想畫面 1：瑜珈老師提醒大家背部要打直，保持垂直直立的姿態。\n\n聯想畫面 2：他是一個正直且品格高尚的人，從不做違背良心的事。\n\n高效擴充：由 up（向上）加上 right（正直、右邊）組成，象徵昂首挺胸的正直形象。\nKK 音標：[əˋpraɪt] -> 主重音在第二音節 right，唸起來像「ㄜˋ普萊特」。\n\n常見同義字：\n\nvertical（垂直的，幾何學用語）\n\nerect（直立的、豎立的）\n\nhonest（誠實的、正直的）",
  "uprooting": "諧音聯想：\n拆解 / 諧音：up（向上）+ root（根）+ ing。\n\n聯想畫面 1：農夫用力把雜草連根拔起，根部向上，這就是根除。\n\n聯想畫面 2：戰爭迫使難民離開家鄉，就像樹木被連根拔起，被迫離開出生地。\n\n高效擴充：root 是根，uproot 就是把根拔起來，引申為徹底消除或被迫遷徙。\nKK 音標：[͵ʌpˋrutɪŋ] -> 重音在第二音節，root 的 oo 發長母音。\n\n常見同義字：\n\nEradication（根除，常用於疾病或問題）\n\nDisplacement（流離失所，強調被迫離開家園）\n\nRemoval（移除，較一般）",
  "upset": "諧音聯想：\n諧音：「阿趴賽得」考試沒考好，整個人心煩意亂、心情非常不高興。\n\n聯想畫面 1：聽到壞消息時眉頭深鎖，情緒感到非常沮喪與心煩意亂。\n\n聯想畫面 2：吃壞肚子導致腸胃不適，整個人躺在床上感到十分難受。\n\n高效擴充：up（向上）加 set（放置），把東西打翻或心思弄亂。\nKK 音標：[əpˋsɛt] -> 主重音在第二音節 [ˋsɛt]，前面的 [əp] 輕唸。\n\n常見同義字：\n\ndisturbed（心神不定的，受干擾的）\n\nworried（擔心的，焦慮的）\n\ndisappointed（失望的，因期待落空而不高興）",
  "upstairs": "字根幽默拆解法：up（沿階梯往上層走）＋ stairs（一階階踏板樓梯）\n\n構造聯想：upstairs 就是抱著剛洗好的衣服「沿階梯往上層走」，踩上木造「一階階踏板樓梯」回到樓上房間。\n\n記憶畫面：吃飽晚餐後小男孩抱著漫畫書「沿階梯往上層走」，輕快跨上「一階階踏板樓梯」跑進自己的樓上 (upstairs) 書房準備寫日記！",
  "upward": "諧音聯想：\n諧音：「阿趴挖低」\n\n聯想畫面 1：小狗看到貓咪爬到樹上，也興奮地仰起頭向上看，希望自己能跳得跟它一樣高。\n\n聯想畫面 2：今年公司的業績呈現上升的趨勢，讓老闆笑得合不攏嘴。\n\n高效擴充：up（向上）加上 ward（方向），指朝上的或升高的。\nKK 音標：[ˋʌpwɚd] -> 重音在首音節 ʌp，發短促的 u 音。\n\n常見同義字：\nupwards（多作副詞使用）\nrising（上升中的）\nascending（上升的、遞增的）",
  "upwards": "字根幽默拆解法：up（往高空爬升）＋ wards（指明前進方向）\n\n構造聯想：upwards 就是一路朝藍天白雲「往高空爬升」，沿著垂直向天的「指明前進方向」越升越高。\n\n記憶畫面：鹿野高台升空的彩色熱氣球冒出暖火「往高空爬升」，遊客沿著天空箭頭「指明前進方向」越飛越遠，開心看著氣球直直向上地 (upwards) 飄翔！",
  "uranium": "諧音聯想：\n諧音：「有然妳阿姆」\n\n聯想畫面 1：核能發電廠裡有然妳阿姆最擔心的放射性金屬鈾元素。\n\n聯想畫面 2：科學家在實驗室小心翼翼地測量鈾的輻射劑量。\n\n高效擴充：源自天王星 Uranus，因為發現時剛好對應到該行星。\nKK 音標：[jɚˋeniəm] -> 第二音節 e 為重音，唸長音的 e。\n\n常見同義字：\nradium（鐳，另一種常見的放射性元素）\nplutonium（鈽，核武常使用的元素）\nelement（元素，較廣泛的通稱）",
  "urban": "諧音聯想：\n諧音：「歐爸」\n\n聯想畫面 1：帥氣的韓國歐爸走在繁華的都市街頭，吸引眾人目光。\n\n聯想畫面 2：現代人都喜歡往都會區發展，尋求更多工作機會。\n\n高效擴充：urb 字根代表城市，例如 suburb 是郊區。\nKK 音標：[ˋɝbən] -> 重音在第一音節，ɝ 是捲舌長母音。\n\n常見同義字：\n\ncity（城市的、市中心的）\nmetropolitan（大都會的）\nmunicipal（市的、市政的）",
  "urbanity": "諧音聯想：\n拆解：urban（都市）+ ity（性質）\n\n聯想畫面 1：他舉止溫文爾雅，充滿了都市人的精緻與禮貌。\n\n聯想畫面 2：這座城市的建築風格極具雅緻，處處展現出都市的魅力。\n\n高效擴充：源自拉丁語 urbanus，指城市居民的特徵，引申為有教養。\nKK 音標：[ɝˋbænəti] -> 重音在第二音節，注意 b 的發音要飽滿。\n\n常見同義字：\nrefinement（優雅，強調細節）\ncivility（禮貌，強調社交）\npoliteness（客氣，通用）",
  "urbanize": "諧音聯想：\n諧音：阿本奈斯（台語：阿本在那裡死）。\n\n聯想畫面 1：阿本在都市化後的摩天大樓間迷路，感嘆自己在那裡死都沒人知道。\n\n聯想畫面 2：政府推動都市化政策，把原本純樸的鄉村變成了繁華的文雅城市。\n\n高效擴充：字根 urb 代表城市，urban 是都市的，加上 ize 變成動詞。\nKK 音標：[ˋɝbə͵naɪz] -> 第一音節 ɝ 是重音，發音時嘴巴微張，舌頭捲起，唸起來要有力。\n\n常見同義字：\nmodernize（現代化，強調設備與觀念的更新）\ncivilize（教化，強調從野蠻變文明）\ndevelop（開發，泛指各方面的成長與建設）",
  "urge": "諧音聯想：\n諧音：餓急。諧音：「餓急」了就會促使你想趕快去找東西吃，這就是內心的強烈慾望。\n\n聯想畫面 1：老闆不斷催促員工趕快把專案報告交出來，氣氛非常緊張。\n\n聯想畫面 2：深夜突然湧現一股想吃鹹酥雞的衝動，讓人難以抗拒。\n\n高效擴充：常作動詞直接加 on 或名词用法 a sudden urge，形容強大的推力。\nKK 音標：[ɝdʒ] -> 單音節字，捲舌音 ɝ 要飽滿，結尾的 dʒ 摩擦音要清晰。\n\n常見同義字：\n\npress（催促、施壓，多用於情勢逼人）\n\nimpulse（衝動、心血來潮，強調突發性）\n\ndesire（渴望、慾望，範圍較廣泛）",
  "urgency": "諧音聯想：\n諧音：「要急成細」\n\n聯想畫面 1：事情要急成細節，因為情況非常緊急，半點馬虎不得。\n\n聯想畫面 2：急診室外家屬焦急地等待，空氣中充滿了迫切與危急感。\n\n高效擴充：從 urgent（緊急的）變化而來的名詞，字尾 cy 代表狀態。\nKK 音標：[ˋɝdʒənsi] -> 第一音節 ur 是重音，捲舌音要扎實。\n\n常見同義字：\nemergency（緊急情況、突發事件）\npressingness（迫切性，較少見但意思接近）\nhurry（匆忙、急促，口語常用）",
  "urgent": "諧音聯想：\n諧音：「餓緊的」\n\n聯想畫面 1：肚子餓得很緊迫，必須馬上找到餐廳吃飯，情況非常緊急。\n\n聯想畫面 2：主管交辦了一項急件，要求今天下班前必須完成。\n\n高效擴充：字根 urg 催促、驅使。\nKK 音標：[ˋɝdʒənt] -> 重音在第一音節，gent 發 dʒənt 的音。\n\n常見同義字：\n\npressing（緊迫的、重大的）\ncritical（關鍵的、危急的）\nimmediate（立即的、緊迫的）",
  "urgently": "諧音聯想：\n諧音：額緊的。\n\n聯想畫面 1：額頭上的汗水緊繃著，因為事情太緊急了，必須 urgently 完成。\n\n聯想畫面 2：救護車鳴笛聲響起，醫生 urgently 趕往急診室搶救病人。\n\n高效擴充：字根 urge 意為催促，加上 ly 變副詞。\nKK 音標：[ˋɝdʒəntlɪ] -> 第一音節重音，r 音要捲舌。\n\n常見同義字：\n\nimmediately（立刻，強調時間）\n\ndesperately（拼命地，強調程度）\n\ncritically（關鍵地，強調重要性）。",
  "urine": "諧音聯想：\n諧音：「有印」\n\n聯想畫面 1：健康檢查的尿液檢體杯上，清楚地有印上病人的名字。\n\n聯想畫面 2：醫生透過檢驗尿液成分，來判斷身體是否有發炎狀況。\n\n高效擴充：字根 ur 與水、排泄有關，醫學相關單字常出現。\nKK 音標：[ˋjɝən] -> 第一音節 ur 重音，後半部輕輕帶過。\n\n常見同義字：\npee（口語的尿尿、小便）\nwater（口語借代，上廁所的委婉說法）\nfluid（體液，較廣義的生理液體）",
  "us": "諧音聯想：\n諧音：「阿斯」的輕聲尾音。\n\n聯想畫面 1：老闆請我們（us）喝一杯飲料。\n\n聯想畫面 2：這部電影讓觸動了我們（us）的心。\n\n高效擴充：we 的受格，放在動詞或介系詞後面。\nKK 音標：[ʌs] -> 短促的 ʌ 音，結尾 s。\n\n常見同義字：\nwe（主格，放在句首）\nour（所有格，後面接名詞）\nme（我單數的受格）",
  "usable": "諧音聯想：\n拆解：use（使用）+ able（能夠）。\n\n聯想畫面 1：這台舊電腦雖然慢，但還能開機，勉強算是 usable。\n\n聯想畫面 2：這塊木板雖然有裂痕，但做成桌腳還是 usable 的。\n\n高效擴充：字尾 able 表示有能力的，能用的就是 usable。\nKK 音標：[ˋjuzəb(ə)l] -> 重音在第一音節，s 發 z 的濁音。\n\n常見同義字：\n\nutilizable（可利用的）\n\nfit for use（適合使用的）。",
  "usage": "諧音聯想：\n諧音：由誰擠。諧音：「由誰擠」牙膏，這個日常習慣的用法每個人都不太一樣。\n\n聯想畫面 1：字典裡會詳細標註這個英文單字的正確用法與例句。\n\n聯想畫面 2：水費帳單上清楚記錄著這個月家庭用水的總用量。\n\n高效擴充：由動詞 use 加上名詞字尾 age，表示行為或消耗的結果。\nKK 音標：[ˋjusədʒ] -> 主重音在首音節 ju，後面的 sədʒ 輕輕帶過。\n\n常見同義字：\n\nuse（使用、用途，最基礎的通用字）\n\napplication（應用、運用，偏向實務操作）\n\nconsumption（消耗、用量，多指能源或資源）",
  "use": "幽默諧音法：「有事」\n\n發音聯想：use [jus] 唸起來像「有事」就派上用場。\n\n記憶畫面：這把多功能瑞士刀平時收在背包裡，一旦露營「有事」就能立刻拿出來使用 (use)！",
  "used": "諧音聯想：\n諧音：「有用得」\n\n聯想畫面 1：這件衣服雖然是二手用過的，但洗一洗還是很有用得。\n\n聯想畫面 2：我已經習慣（used to）每天早上喝一杯黑咖啡。\n\n高效擴充：動詞 use 的過去分詞轉形容詞使用。\nKK 音標：[juzd] -> 注意結尾發 d 的濁音。\n\n常見同義字：\n\nsecond-hand（二手的、舊的）\n\naccustomed（習慣於...的，常與 to 並用）\n\nutilized（被利用的、被應用的）",
  "useful": "字根幽默拆解法：use（使用、用處）＋ ful（充滿…的）\n\n構造聯想：useful 就是全身上下「充滿」實際「用處」的，代表有用的、實用的。\n\n記憶畫面：這本口袋旅遊手冊「充滿」了各種「用處」，出國查路線時真是超有用又實用的 (useful) 好幫手！",
  "useless": "諧音聯想：\n諧音：由（u）+ 死（s）+ 累死（less）。\n\n聯想畫面 1：買了一個超級複雜的廚房小工具，結果用起來反而更累死人，最後只能丟進垃圾桶，真是無用。\n\n聯想畫面 2：在荒島上撿到一把沒有子彈的槍，對著獅子揮舞，這東西完全無用且無價值。\n\n高效擴充：字尾 -less 表示沒有，use 是使用，沒有用處就是無能或無價值。\nKK 音標：[ˋjusləs] -> 重音在第一音節，唸起來要乾脆俐落。\n\n常見同義字：\n\nfutile（徒勞的，強調努力後無果）\n\npointless（無意義的，指缺乏目的）\n\nvain（徒勞的，常與 in vain 連用）。",
  "user": "諧音聯想：\n諧音：「有色人」\n\n聯想畫面 1：這款新軟體介面很友善，吸引了無數的使用者上網體驗。\n\n聯想畫面 2：客服人員正耐心解答這位註冊用戶在使用上的各種疑問。\n\n高效擴充：動詞 use 加上表人的字尾 er，變成使用者。\nKK 音標：[ˋjuzɚ] -> 主重音在最前面的 ju，尾音 zɚ 輕輕帶過。\n\n常見同義字：\nconsumer（消費者，偏向購買商品的人）\ncustomer（顧客，買東西的人）\nclient（客戶，接受專業服務的人）",
  "usher": "諧音聯想：\n諧音：「阿舍」\n\n聯想畫面 1：有錢的阿舍去看歌劇，有專門的引座員帶領他走到最尊榮的VIP座位。\n\n聯想畫面 2：婚禮現場的迎賓員面帶微笑，親切地引導賓客入席。\n\n高效擴充：動詞與名詞同形，常指劇場或典禮的接待人員。\nKK 音標：[ˋʌʃɚ] -> 第一音節 us 是重音，sh 發擦音。\n\n常見同義字：\nguide（導遊、引導者，範圍較廣）\nhost（主人、節目主持人，負責招呼客人）\nattendant（服務員、隨從，泛指工作人員）",
  "usual": "諧音聯想：\n諧音：「有九折的」\n\n聯想畫面 1：這家店通常都有九折的優惠，是常客的最愛。\n\n聯想畫面 2：按照平常慣常的做法，我們下午三點開會。\n\n高效擴充：字尾加 ly 變成 usually（通常）。\nKK 音標：[ˋjuʒəwəl] -> 重音在第一音節，注意 zh 的摩擦音。\n\n常見同義字：\n\ncommon（常見的、普遍的）\n\nnormal（正常的、正規的）\n\nusytematic（有系統的，非同義但拼寫易混淆）",
  "usually": "諧音聯想：\n諧音：「有秀瓦力」\n\n聯想畫面 1：機器人瓦力通常會清理垃圾，表現很優秀。\n\n聯想畫面 2：我一般會在早上喝一杯黑咖啡。\n\n高效擴充：由usual加上ly形成，表示常態。\nKK 音標：[ˋjuʒəwəli] -> 主重音在第一個音節ju上，注意zh的摩擦音。\n\n常見同義字：\n\ngenerally（通常，範圍較廣的大致情況）\n\nnormally（正常地，符合常態的習慣）\n\ncustomarily（習慣上，依照習俗或慣例）",
  "utensil": "諧音聯想：\n諧音：「有貼洗碗」\n\n聯想畫面 1：餐廳廚房裡有貼洗碗公告，提醒員工保持各種烹飪器皿的乾淨。\n\n聯想畫面 2：露營時帶了齊全的餐具與炊具，方便野外開伙。\n\n高效擴充：通常指廚房用具或日常小型器皿。\nKK 音標：[juˋtɛnsəl] -> 第二音節 ten 是重音，發短促的 e。\n\n常見同義字：\ntool（工具，範圍廣泛）\nappliance（家用電器，通常指插電大型器具）\ninstrument（儀器、樂器，強調精密或專業）",
  "utilitarian": "諧音聯想：\n諧音：「優提力替安」\n\n聯想畫面 1：工程師設計了一款功利實用的工具箱，優化了提取工具的力道，替安檢省下不少時間。\n\n聯想畫面 2：辦公室的裝潢一切講求實用主義，沒有多餘的花俏裝飾。\n\n高效擴充：由 utility（效用、實用）衍生而來的形容詞與名詞。\nKK 音標：[͵jutɪlɪˋteriən] -> 主重音在倒數第二音節 [ter]，注意次重音在字首 [ju]。\n\n常見同義字：\npractical（實際的，強調在生活中好用）\nfunctional（功能性的，強調具備具體用途）\npragmatic（務實的，做事講求實際效果）",
  "utility": "諧音聯想：\n諧音：「有踢啦體」\n\n聯想畫面 1：這台多功能健身車有踢啦體能訓練的實用價值與多種功能。\n\n聯想畫面 2：每個月收到水電瓦斯等公用事業帳單，提醒我們要節約能源。\n\n高效擴充：utilize（利用）的名詞形態，兼具實用與水電公用事業意思。\nKK 音標：[juˋtɪləti] -> 第二音節 til 是重音，念短 i。\n\n常見同義字：\nusefulness（有用性、效用）\nservice（服務，常指公共服務）\nconvenience（便利性，指帶來方便的事物）",
  "utilization": "諧音聯想：\n拆解 / 諧音：優提哩（台語：有提哩）再選。\n\n聯想畫面 1：老闆在利用資源時，總會說這東西有提哩（有提起來）再選用才有效率。\n\n聯想畫面 2：工廠將廢棄物回收再利用，最大化資源的價值。\n\n高效擴充：字根 util 代表有用，utilize 是動詞，加上 tion 變成名詞。\nKK 音標：[͵jutələˋzeʃən] -> 第三音節 ze 是主重音，唸起來要拉長且響亮。\n\n常見同義字：\nuse（最基礎的用法，泛指使用）\napplication（應用，強調將某物運用在特定目的上）\nconsumption（消耗，強調資源被使用掉的過程）",
  "utilize": "諧音聯想：\n諧音：「有去來賴」這工具真好用，大家搶著利用。\n\n聯想畫面 1：你買了一台多功能吸塵器，每天有去來賴地頻繁利用它來打掃家裡。\n\n聯想畫面 2：公司導入了一套新軟體，全體員工都在高效率地利用它來處理日常行政。\n\n高效擴充：字首 ut 代表使用，字尾 ize 動詞化字尾，與 use 相比更強調有效利用資源。\nKK 音標：[ˋjutə͵laɪz] -> 第一音節重音在 ju，發悠長音，後面吐氣唸 laɪz。\n\n常見同義字：\n\nuse（最常見的基本用語，指一般使用）\n\nemploy（雇用或運用，多指運用技能或資金）\n\napply（應用，側重將理論或方法套用到實際狀況）",
  "utmost": "諧音聯想：\n諧音：「阿媽罵死特」\n\n聯想畫面 1：阿媽叮嚀做事要盡到最大的努力，不然會被罵死特的極度嚴格要求嚇到。\n\n聯想畫面 2：運動員在決賽中使出渾身解數，發揮出極度的極限實力。\n\n高效擴充：ut（出、極端）加上 most（最多），也就是最多、最極致。\nKK 音標：[ˋʌt͵most] -> 第一音節 ut 是重音，t 要輕輕彈舌。\n\n常見同義字：\nmaximum（最大值、最大量的）\nsupreme（至高無上的、極度的）\nuttermost（最遠的、極度的，與 utmost 幾近同義）",
  "utter": "諧音聯想：\n諧音：「阿爸」\n\n聯想畫面 1：阿爸生氣時，口中 utter 說出完全的氣話，徹底把氣出完。\n\n聯想畫面 2：他在台上 utter 發表心聲，字字句句都是發自內心的真話。\n\n高效擴充：利用字根理解，out 外出加字尾變化，延伸出把話講出來的意思。\nKK 音標：[ˋʌtɚ] -> 重音在第一音節的 ʌ，嘴巴放鬆下巴微開，短促有力地發出短音。\n\n常見同義字：\ntotal（完全的，通常修飾名詞強調程度）\nabsolute（絕對的，較強烈且正式）\nspeak（說話，動作本身較為中性普遍）"
});
